import Foundation

/// 사회(지리·일반사회·역사·도덕/윤리) 개념 사전: 초등 → 대학교
extension DoitCurriculum {
    static let social: [CurriculumEntry] = [
        // MARK: - 초등

        ce(.elementary, "우리 고장의 모습", ["고장", "우리 고장"], "고장은 우리가 살고 있는 곳과 그 주변 지역을 말해요. 고장마다 산, 강, 바다 같은 자연환경과 시장, 학교 같은 장소가 달라서 사람들의 생활 모습도 조금씩 달라요.\n예: 바닷가 고장에서는 고기잡이를, 들이 넓은 고장에서는 농사를 많이 지어요."),
        ce(.elementary, "우리 고장의 모습", ["문화유산", "문화재", "국가유산"], "문화유산은 조상들이 남긴 것 가운데 역사적·예술적 가치가 있어 후손에게 물려줄 만한 것이에요. 흔히 건축물이나 유물처럼 형태가 있는 유형 문화유산과 춤, 노래, 기술처럼 형태가 없는 무형 문화유산으로 나눠요. 우리나라는 2024년부터 이를 아울러 '국가유산'이라는 이름을 쓰고 있어요.\n예: 경주 불국사는 형태가 있는 문화유산, 판소리는 무형의 유산이에요."),

        ce(.elementary, "지역의 위치와 특성", ["지도", "지도의 요소"], "지도는 땅의 모습을 일정한 비율로 줄여 약속된 기호로 평면에 나타낸 그림이에요. 지도에는 방위, 기호와 범례, 축척, 등고선 같은 요소가 있어서 이것을 알면 지도를 정확하게 읽을 수 있어요.\n예: 지도를 보고 처음 가는 박물관까지 가는 길을 찾을 수 있어요."),
        ce(.elementary, "지역의 위치와 특성", ["방위", "방위표", "동서남북"], "방위는 동서남북처럼 방향을 나타내는 말이에요. 지도에 방위표가 있으면 그 표시를 따르고, 방위표가 없으면 보통 지도의 위쪽이 북쪽이에요.\n예: 지도 위쪽이 북쪽이면 오른쪽은 동쪽, 왼쪽은 서쪽, 아래쪽은 남쪽이에요."),
        ce(.elementary, "지역의 위치와 특성", ["기호와 범례", "지도 기호", "범례"], "지도 기호는 학교, 병원, 산, 논 같은 땅 위의 여러 모습을 간단한 그림이나 글자로 약속해 나타낸 것이에요. 범례는 지도에 쓰인 기호와 그 뜻을 한곳에 모아 정리해 둔 표예요.\n예: 범례를 보면 지도 속 기호가 학교인지 우체국인지 알 수 있어요."),
        ce(.elementary, "지역의 위치와 특성", ["축척", "지도의 축척"], "축척은 실제 거리를 지도에 얼마나 줄여서 나타냈는지 보여 주는 비율이에요. 1:50,000은 지도에서 1cm가 실제로는 50,000cm, 즉 500m라는 뜻이에요. 축척이 클수록(분모가 작을수록) 좁은 지역을 자세히 나타내요.\n예: 1:5,000 지도는 1:50,000 지도보다 우리 동네를 더 자세히 보여 줘요."),
        ce(.elementary, "지역의 위치와 특성", ["등고선", "땅의 높낮이"], "등고선은 지도에서 바다 면으로부터 높이가 같은 곳을 이어 그린 선이에요. 등고선 간격이 좁으면 경사가 급하고, 넓으면 경사가 완만해요. 지도에서는 색으로도 높낮이를 나타내는데, 보통 낮은 곳은 초록색, 높아질수록 노란색과 갈색으로 칠해요.\n예: 등고선이 촘촘하게 모인 산비탈은 오르기 힘든 가파른 곳이에요."),

        ce(.elementary, "지역의 공공 기관과 주민 참여", ["공공 기관", "공공기관"], "공공 기관은 주민 전체의 이익과 편리를 위해 국가나 지방 자치 단체가 세우거나 관리하는 곳이에요. 개인의 이익이 아니라 모두를 위해 일한다는 점이 특징이에요.\n예: 시청·군청, 경찰서, 소방서, 보건소, 우체국이 공공 기관이에요."),
        ce(.elementary, "지역의 공공 기관과 주민 참여", ["주민 참여", "지역 문제 해결"], "주민 참여는 주민들이 지역의 일을 결정하고 지역 문제를 해결하는 과정에 직접 참여하는 것이에요. 주민 회의, 서명 운동, 공청회 참석, 누리집에 의견 올리기 등의 방법이 있어요. 주민 참여가 활발할수록 주민이 원하는 지역을 만들 수 있어요.\n예: 놀이터가 위험하다는 의견을 시청 누리집에 올려 고치게 할 수 있어요."),
        ce(.elementary, "지역의 공공 기관과 주민 참여", ["지방 자치", "지방 자치 제도", "지방자치"], "지방 자치는 지역 주민이 직접 뽑은 대표를 통해 그 지역의 일을 스스로 처리하는 제도예요. 주민은 선거로 지방 자치 단체장(시장, 군수, 도지사 등)과 지방 의회 의원을 뽑아요.\n예: 우리 시의 시장과 시의회 의원은 시민들이 선거로 뽑아요."),

        ce(.elementary, "촌락과 도시의 생활 모습", ["촌락", "시골 마을"], "촌락은 자연환경을 주로 이용해 살아가는 사람들이 모여 사는 곳이에요. 주로 하는 일에 따라 농촌, 어촌, 산지촌으로 나눠요. 도시에 비해 인구가 적고 자연과 가까운 생활을 해요.\n예: 논과 밭이 펼쳐진 마을은 농사를 짓는 농촌이에요."),
        ce(.elementary, "촌락과 도시의 생활 모습", ["농촌", "농업 마을"], "농촌은 주로 들이 넓고 물을 얻기 쉬운 곳에서 농사를 지으며 살아가는 촌락이에요. 논, 밭, 비닐하우스, 과수원 등을 볼 수 있어요. 요즘은 기계를 써서 일손을 줄이고, 체험 마을이나 특산물 판매로 소득을 높이기도 해요.\n예: 벼농사를 짓는 마을, 사과 과수원이 많은 마을이 농촌이에요."),
        ce(.elementary, "촌락과 도시의 생활 모습", ["어촌", "바닷가 마을"], "어촌은 바다와 가까운 곳에서 고기잡이나 양식, 김·미역 기르기 등을 하며 살아가는 촌락이에요. 항구와 배, 수산물 시장, 갯벌 등을 볼 수 있어요.\n예: 바닷가 마을에서 굴과 김을 양식하는 모습을 볼 수 있어요."),
        ce(.elementary, "촌락과 도시의 생활 모습", ["산지촌", "산간 마을"], "산지촌은 산이 많은 지역에서 산을 이용해 살아가는 촌락이에요. 밭농사, 약초나 버섯 기르기, 목축, 나무 가공 등을 하고, 최근에는 휴양림이나 스키장 같은 관광 산업도 발달했어요.\n예: 강원도 산간 마을에서 고랭지 배추를 기르는 모습이 산지촌의 생활이에요."),
        ce(.elementary, "촌락과 도시의 생활 모습", ["도시", "도시의 특징"], "도시는 많은 사람이 좁은 지역에 모여 살며 주로 공업, 상업, 서비스업에 종사하는 곳이에요. 높은 건물과 아파트, 다양한 교통 시설과 편의 시설이 모여 있어요.\n예: 서울, 부산, 대구 같은 큰 도시에는 지하철과 대형 병원, 백화점이 있어요."),
        ce(.elementary, "촌락과 도시의 생활 모습", ["도시 문제", "교통 혼잡"], "도시 문제는 도시에 사람과 시설이 너무 많이 모이면서 생기는 여러 문제예요. 교통 혼잡, 주택 부족, 환경 오염, 쓰레기 처리 문제 등이 있어요. 대중교통 확대, 신도시 개발, 분리배출 같은 노력으로 해결하려고 해요.\n예: 출퇴근 시간에 도로가 막히는 것은 대표적인 도시 문제예요."),
        ce(.elementary, "촌락과 도시의 생활 모습", ["촌락과 도시의 교류", "도농 교류"], "촌락과 도시는 서로 필요한 것을 주고받으며 교류해요. 촌락은 도시에 농수산물을 보내고, 도시는 촌락에 공산품과 의료·문화 서비스를 제공해요. 자매결연, 농산물 직거래, 체험 학습 등으로 교류해요.\n예: 도시 학교 학생들이 농촌에 가서 모내기 체험을 하는 것도 교류예요."),

        ce(.elementary, "필요한 것의 생산과 교환", ["희소성", "자원의 희소성"], "희소성은 사람들의 욕구에 비해 그것을 채워 줄 자원이 부족한 상태를 말해요. 자원이 부족하기 때문에 우리는 무엇을 얼마나 쓸지 선택해야 해요. 같은 물건이라도 원하는 사람에 비해 양이 적으면 희소성이 커요.\n예: 사막에서는 물의 희소성이 매우 커요."),
        ce(.elementary, "필요한 것의 생산과 교환", ["합리적 선택", "현명한 선택"], "합리적 선택은 정해진 돈과 시간으로 가장 큰 만족을 얻을 수 있도록 고르는 것이에요. 가격, 품질, 디자인, 필요성 같은 선택 기준을 세우고 여러 대안을 비교한 뒤 결정해요.\n예: 운동화를 살 때 가격과 편안함을 비교해 나에게 가장 알맞은 것을 고르는 거예요."),
        ce(.elementary, "필요한 것의 생산과 교환", ["생산", "생산 활동"], "생산은 사람들에게 필요한 물건(재화)을 만들거나 서비스를 제공하는 활동이에요. 농사짓기, 물건 만들기뿐 아니라 물건을 나르거나 파는 일, 가르치거나 치료하는 일도 생산에 해당해요.\n예: 빵 공장에서 빵을 만드는 일, 의사가 환자를 치료하는 일 모두 생산이에요."),
        ce(.elementary, "필요한 것의 생산과 교환", ["가계와 기업", "경제 주체"], "가계와 기업은 경제 활동을 하는 대표적인 주체예요. 가계는 기업에 노동력을 제공하고 받은 소득으로 소비를 하고, 기업은 가계가 필요로 하는 재화와 서비스를 생산해 이윤을 얻어요. 여기에 정부를 더해 3대 경제 주체라고 해요.\n예: 부모님이 회사에서 일하고 월급을 받는 것은 가계가 기업에 노동을 제공하는 거예요."),
        ce(.elementary, "필요한 것의 생산과 교환", ["시장", "교환"], "시장은 물건이나 서비스를 사려는 사람과 팔려는 사람이 만나 거래가 이루어지는 곳이에요. 재래시장처럼 눈에 보이는 시장도 있고, 인터넷 쇼핑이나 주식 시장처럼 눈에 보이지 않는 시장도 있어요.\n예: 온라인 쇼핑몰에서 책을 사는 것도 시장에서 거래하는 거예요."),

        ce(.elementary, "인권 존중과 정의로운 사회", ["인권", "사람의 권리"], "인권은 사람이라면 누구나 태어날 때부터 가지는 기본적인 권리예요. 성별, 나이, 피부색, 장애, 재산과 관계없이 모든 사람에게 똑같이 주어지고, 누구도 함부로 빼앗을 수 없어요.\n예: 차별받지 않을 권리, 교육받을 권리, 자유롭게 생각하고 말할 권리가 인권이에요."),
        ce(.elementary, "인권 존중과 정의로운 사회", ["세계 인권 선언", "세계 인권의 날"], "세계 인권 선언은 1948년 12월 10일 국제 연합(UN) 총회에서 채택된 선언이에요. 제2차 세계 대전의 참혹한 인권 침해를 반성하며 모든 사람이 누려야 할 기본적인 권리와 자유를 정리했어요. 그래서 12월 10일은 세계 인권의 날이에요.\n예: 제1조는 모든 사람이 태어날 때부터 자유롭고, 존엄성과 권리에서 평등하다고 밝혀요."),
        ce(.elementary, "인권 존중과 정의로운 사회", ["유엔 아동 권리 협약", "어린이 권리", "아동권리협약"], "유엔 아동 권리 협약은 1989년 국제 연합 총회에서 채택된, 18세 미만 아동의 권리를 정한 국제 약속이에요. 생존권, 보호권, 발달권, 참여권을 아동의 4대 권리로 꼽아요. 우리나라는 1991년에 이 협약을 비준했어요.\n예: 어린이가 놀고 쉴 권리, 자기 의견을 말할 권리도 이 협약에 담겨 있어요."),
        ce(.elementary, "인권 존중과 정의로운 사회", ["헌법", "대한민국 헌법"], "헌법은 나라를 운영하는 기본 원칙과 국민의 권리와 의무를 정한 나라의 최고 법이에요. 다른 모든 법은 헌법에 어긋나면 안 돼요. 헌법을 고치려면 국회 의결과 국민 투표를 거쳐야 할 만큼 엄격한 절차가 필요해요.\n예: 대한민국 헌법 제1조는 '대한민국은 민주공화국이다'라고 밝히고 있어요."),
        ce(.elementary, "인권 존중과 정의로운 사회", ["국민의 의무", "국민의 기본 의무"], "국민의 의무는 국가 공동체를 유지하기 위해 국민이 지켜야 할 책임이에요. 우리 헌법에는 납세의 의무, 국방의 의무, 교육의 의무, 근로의 의무, 환경 보전의 의무, 재산권 행사를 공공복리에 맞게 할 의무가 나와 있어요.\n예: 세금을 내는 것, 자녀에게 교육을 받게 하는 것이 국민의 의무예요."),

        ce(.elementary, "우리나라의 정치 발전", ["민주주의", "민주 정치"], "민주주의는 나라의 주인인 국민이 나라의 중요한 일을 결정하는 정치 방식이에요. 인간의 존엄, 자유, 평등을 기본 가치로 삼아요. 생활 속에서는 대화와 타협, 관용, 비판적 태도, 양보가 필요해요.\n예: 학급 회의에서 모두가 의견을 내고 함께 결정하는 것도 민주주의를 실천하는 거예요."),
        ce(.elementary, "우리나라의 정치 발전", ["선거", "투표"], "선거는 국민이 투표로 나라나 지역의 일을 맡을 대표를 뽑는 일이에요. 우리나라는 대통령 선거, 국회 의원 선거, 지방 선거 등을 치르며, 만 18세 이상 국민에게 선거권이 있어요. 선거는 국민이 주권을 행사하는 대표적인 방법이에요.\n예: 국회 의원 선거에서 우리 지역의 국회 의원을 뽑아요."),
        ce(.elementary, "우리나라의 정치 발전", ["선거의 4대 원칙", "민주 선거의 원칙"], "민주 선거는 네 가지 원칙을 지켜요. 보통 선거는 일정한 나이가 되면 누구나 투표할 수 있는 것, 평등 선거는 누구나 한 사람이 한 표씩 가지는 것, 직접 선거는 자신이 직접 투표하는 것, 비밀 선거는 누구에게 투표했는지 남이 모르게 하는 것이에요.\n예: 투표소에 가림막이 있는 것은 비밀 선거를 지키기 위해서예요."),
        ce(.elementary, "우리나라의 정치 발전", ["다수결의 원칙", "다수결"], "다수결의 원칙은 의견이 다를 때 더 많은 사람이 찬성하는 쪽으로 결정하는 방법이에요. 짧은 시간에 결정을 내릴 수 있지만, 다수의 의견이 항상 옳은 것은 아니므로 결정 전에 충분히 토론하고 소수의 의견도 존중해야 해요.\n예: 현장 체험학습 장소를 반 친구들의 투표로 정하는 거예요."),
        ce(.elementary, "우리나라의 정치 발전", ["삼권 분립", "권력 분립"], "삼권 분립은 국가 권력을 입법권, 행정권, 사법권으로 나눠 서로 다른 기관이 맡게 하는 제도예요. 우리나라는 국회가 법을 만들고, 정부가 법에 따라 나라 살림을 하며, 법원이 법에 따라 재판해요. 권력이 한곳에 몰려 함부로 쓰이는 것을 막아 국민의 자유와 권리를 지키려는 것이에요.\n예: 국회는 국정 감사를 통해 정부가 일을 잘하는지 살펴봐요."),
        ce(.elementary, "우리나라의 정치 발전", ["민주화 과정", "우리나라 민주주의의 발전"], "우리나라 국민은 여러 차례의 민주화 운동으로 민주주의를 발전시켰어요. 1960년 4·19 혁명, 1980년 5·18 민주화 운동, 1987년 6월 민주 항쟁을 거치며 국민이 대통령을 직접 뽑는 직선제가 다시 이루어졌어요.\n예: 6월 민주 항쟁 이후 대통령 직선제로 헌법이 바뀌었어요."),

        ce(.elementary, "옛사람들의 삶과 문화", ["고조선", "단군왕검", "8조법"], "고조선은 우리 역사에서 처음 세워진 나라예요. 『삼국유사』에 따르면 단군왕검이 기원전 2333년에 세웠다고 전해요. 사람을 죽인 자는 사형에 처한다는 내용 등이 담긴 8조법이 있었고, 기원전 108년 중국 한나라의 공격으로 멸망했어요.\n예: 고인돌과 비파형 동검은 고조선을 대표하는 유적과 유물이에요."),
        ce(.elementary, "옛사람들의 삶과 문화", ["삼국 시대", "고구려 백제 신라"], "삼국 시대는 고구려, 백제, 신라가 한반도와 만주에서 경쟁하며 발전한 시기예요. 4세기에는 백제(근초고왕), 5세기에는 고구려(광개토 대왕·장수왕), 6세기에는 신라(진흥왕)가 전성기를 누렸어요. 한반도 남쪽에는 가야도 있었어요.\n예: 고구려 광개토 대왕릉비, 백제 금동 대향로, 신라 첨성대가 이 시대의 문화유산이에요."),
        ce(.elementary, "옛사람들의 삶과 문화", ["통일 신라와 발해", "남북국"], "신라는 당나라와 손잡고 백제(660년)와 고구려(668년)를 무너뜨린 뒤, 당나라 군대까지 몰아내고 676년에 삼국 통일을 이루었어요. 698년에는 고구려 장수 출신 대조영이 발해를 세워 북쪽 땅을 다스렸어요.\n예: 경주 불국사와 석굴암은 통일 신라의 대표적인 문화유산이에요."),
        ce(.elementary, "옛사람들의 삶과 문화", ["고려", "왕건", "고려청자"], "고려는 918년 왕건이 세운 나라로, 936년에 후삼국을 통일했어요. 불교를 중시했고, 고려청자와 팔만대장경, 금속 활자 같은 뛰어난 문화유산을 남겼어요. 1392년 이성계가 조선을 세우면서 막을 내렸어요.\n예: 현존하는 세계에서 가장 오래된 금속 활자본인 『직지심체요절』은 1377년 고려에서 인쇄되었어요."),
        ce(.elementary, "옛사람들의 삶과 문화", ["조선", "조선 왕조", "이성계"], "조선은 1392년 이성계가 세운 나라로, 한양(지금의 서울)을 도읍으로 삼았어요. 유교(성리학)를 나라를 다스리는 기본 이념으로 삼았고, 세종 때 훈민정음을 만드는 등 과학과 문화가 크게 발전했어요. 1897년 나라 이름을 대한 제국으로 바꾸었어요.\n예: 경복궁, 측우기, 『조선왕조실록』은 조선의 대표적인 문화유산이에요."),
        ce(.elementary, "옛사람들의 삶과 문화", ["임진왜란", "이순신", "한산도 대첩"], "임진왜란은 1592년 일본이 조선을 침략하면서 시작되어 1598년까지 이어진 전쟁이에요. 이순신 장군이 이끄는 수군이 한산도 대첩 등에서 크게 이기고, 곳곳에서 의병이 일어나 나라를 지켰어요.\n예: 이순신은 거북선을 활용했고, 『난중일기』에 전쟁 기록을 남겼어요."),

        ce(.elementary, "사회의 새로운 변화와 오늘날의 우리", ["일제 강점기", "국권 피탈", "독립운동"], "일제 강점기는 1910년 국권 피탈부터 1945년 광복까지 일본이 우리나라를 강제로 지배한 시기예요. 우리 민족은 1919년 3·1 운동을 일으키고 대한민국 임시 정부를 세우는 등 독립을 위해 끊임없이 싸웠어요.\n예: 유관순, 김구, 윤봉길, 안창호는 대표적인 독립운동가예요."),
        ce(.elementary, "사회의 새로운 변화와 오늘날의 우리", ["대한민국 정부 수립", "광복과 정부 수립"], "1945년 8월 15일 광복을 맞았지만 한반도는 북위 38도선을 경계로 남쪽에는 미군, 북쪽에는 소련군이 주둔했어요. 1948년 5월 10일 남한에서 총선거가 치러져 제헌 국회가 헌법을 만들었고, 같은 해 8월 15일 대한민국 정부가 수립되었어요.\n예: 7월 17일 제헌절은 1948년 헌법이 공포된 날을 기념해요."),
        ce(.elementary, "사회의 새로운 변화와 오늘날의 우리", ["6·25 전쟁", "한국 전쟁"], "6·25 전쟁은 1950년 6월 25일 북한의 남침으로 시작된 전쟁이에요. 국제 연합군과 중국군이 참전하며 전쟁이 커졌고, 1953년 7월 27일 정전 협정이 맺어지면서 휴전선이 생겼어요. 많은 사람이 목숨을 잃고 이산가족이 생기는 큰 피해를 남겼어요.\n예: 남북은 지금도 전쟁을 완전히 끝낸 것이 아니라 정전 상태예요."),

        ce(.elementary, "세계 여러 나라의 자연과 문화", ["대륙과 대양", "6대륙 5대양"], "지구의 땅은 아시아, 유럽, 아프리카, 북아메리카, 남아메리카, 오세아니아의 6대륙으로 나눌 수 있어요(남극 대륙을 더해 7대륙이라고도 해요). 바다는 태평양, 대서양, 인도양, 북극해, 남극해의 5대양으로 나눠요. 가장 넓은 대륙은 아시아, 가장 넓은 바다는 태평양이에요.\n예: 우리나라는 아시아 대륙의 동쪽, 태평양과 가까운 곳에 있어요."),
        ce(.elementary, "세계 여러 나라의 자연과 문화", ["지구본과 세계 지도", "지구의"], "지구본은 지구를 작게 줄인 모형으로, 땅의 모양과 크기, 거리를 실제와 거의 같은 비율로 보여 줘요. 세계 지도는 둥근 지구를 평면에 펼친 것이라 한눈에 보기 편하지만, 특히 극지방으로 갈수록 땅의 모양이나 면적이 실제와 다르게 나타나요.\n예: 메르카토르 도법으로 그린 지도에서는 그린란드가 실제보다 훨씬 크게 보여요."),

        ce(.elementary, "통일 한국의 미래와 지구촌의 평화", ["남북통일", "통일의 필요성"], "남북통일은 분단된 남한과 북한이 하나의 나라가 되는 것을 말해요. 통일이 되면 이산가족의 아픔을 덜고, 전쟁의 위협을 줄이며, 국토와 자원, 인력을 함께 활용해 더 발전할 수 있다는 기대가 있어요. 남북은 체육 교류, 이산가족 상봉 등 다양한 교류를 해 왔어요.\n예: 남북 단일팀이 국제 대회에 함께 출전한 적이 있어요."),
        ce(.elementary, "통일 한국의 미래와 지구촌의 평화", ["지구촌 갈등", "국제 분쟁"], "지구촌 갈등은 영토, 자원, 종교, 민족, 역사 문제 등으로 나라나 집단 사이에 일어나는 다툼이에요. 갈등이 전쟁이나 테러로 번지면 많은 사람이 다치고 난민이 생겨요. 대화와 협력, 국제기구의 중재로 평화롭게 해결하려는 노력이 필요해요.\n예: 전쟁을 피해 고향을 떠난 난민을 돕는 활동이 국제적으로 이루어져요."),
        ce(.elementary, "통일 한국의 미래와 지구촌의 평화", ["지구촌 환경 문제", "지구 온난화"], "지구촌 환경 문제는 한 나라만의 노력으로 해결하기 어렵고 여러 나라에 영향을 주는 환경 문제예요. 지구 온난화, 사막화, 열대 우림 파괴, 해양 쓰레기, 미세 먼지 등이 있어요. 나라끼리 국제 협약을 맺고, 개인도 에너지 절약과 재활용을 실천해야 해요.\n예: 지구 온난화로 빙하가 녹아 해수면이 높아지고 있어요."),
        ce(.elementary, "통일 한국의 미래와 지구촌의 평화", ["국제 연합", "유엔", "UN"], "국제 연합(UN)은 세계 평화와 안전을 지키고 나라 간 협력을 이끌기 위해 1945년에 만든 국제기구예요. 본부는 미국 뉴욕에 있고, 유니세프(UNICEF), 유네스코(UNESCO), 세계 보건 기구(WHO) 같은 여러 기구와 함께 일해요. 우리나라는 1991년에 북한과 함께 가입했어요.\n예: 유니세프는 세계 어린이들의 건강과 교육을 도와요."),
        ce(.elementary, "통일 한국의 미래와 지구촌의 평화", ["비정부 기구", "NGO"], "비정부 기구(NGO)는 정부와 관계없이 시민들이 자발적으로 만든 단체로, 국경을 넘어 환경, 인권, 빈곤, 평화 같은 지구촌 문제를 해결하려고 활동해요. 정부나 기업의 이익보다 인류 공동의 이익을 위해 일한다는 점이 특징이에요.\n예: 국경 없는 의사회, 그린피스, 국제 앰네스티가 대표적인 비정부 기구예요."),

        // MARK: - 중학교

        ce(.middle, "내가 사는 세계", ["위도", "위선"], "위도는 적도를 0도로 하여 남북으로 각각 90도까지 나타낸 위치 값이에요. 같은 위도를 이은 선을 위선이라고 하고, 적도 북쪽은 북위, 남쪽은 남위라고 해요. 위도에 따라 받는 햇빛의 양이 달라 기후가 크게 달라져요.\n예: 서울은 대략 북위 37.5도에 있어요."),
        ce(.middle, "내가 사는 세계", ["경도", "경선"], "경도는 본초 자오선을 0도로 하여 동서로 각각 180도까지 나타낸 위치 값이에요. 같은 경도를 이은 선을 경선이라고 하며, 본초 자오선 동쪽은 동경, 서쪽은 서경이에요. 경도 차이는 지역 간의 시간 차이(시차)를 만들어요.\n예: 서울은 대략 동경 127도에 있어요."),
        ce(.middle, "내가 사는 세계", ["본초 자오선", "그리니치 천문대"], "본초 자오선은 경도 0도의 기준이 되는 경선으로, 영국 런던의 그리니치 천문대를 지나요. 1884년 국제 회의에서 세계 공통의 기준으로 정해졌어요. 세계 시간의 기준도 이 선을 바탕으로 해요.\n예: 그리니치 천문대에서는 본초 자오선을 사이에 두고 동반구와 서반구에 한 발씩 올려 볼 수 있어요."),
        ce(.middle, "내가 사는 세계", ["시차", "표준시"], "시차는 경도 차이 때문에 생기는 지역 간의 시간 차이예요. 지구는 하루 24시간 동안 360도를 돌기 때문에 경도 15도마다 1시간씩 차이가 나요. 각 나라는 기준이 되는 경선을 정해 표준시로 사용해요.\n예: 우리나라는 동경 135도를 표준 경선으로 써서 영국보다 9시간 빨라요."),
        ce(.middle, "내가 사는 세계", ["날짜 변경선", "국제 날짜 변경선"], "날짜 변경선은 대체로 경도 180도 선을 따라 정한, 날짜가 바뀌는 기준선이에요. 이 선을 서쪽에서 동쪽으로 넘으면 날짜를 하루 늦추고, 동쪽에서 서쪽으로 넘으면 하루 더해요. 한 나라 안에서 날짜가 갈리지 않도록 육지를 피해 구불구불하게 그어져 있어요.\n예: 한국에서 미국으로 가는 비행기를 타면 출발한 날짜보다 이른 날짜에 도착하기도 해요."),

        ce(.middle, "우리와 다른 기후, 다른 생활", ["기후", "기후 요소", "기후 요인"], "기후는 한 지역에서 오랜 기간에 걸쳐 나타나는 평균적인 대기 상태예요. 매일 바뀌는 날씨와 달리 보통 30년 정도의 평균값으로 나타내요. 기온, 강수량, 바람 등을 기후 요소라 하고, 위도, 지형, 바다와의 거리처럼 기후에 영향을 주는 것을 기후 요인이라고 해요.\n예: '오늘 비가 온다'는 날씨, '여름에 비가 많이 온다'는 기후예요."),
        ce(.middle, "우리와 다른 기후, 다른 생활", ["열대 기후", "열대 우림"], "열대 기후는 가장 추운 달의 평균 기온이 18℃ 이상인, 1년 내내 더운 기후예요. 주로 적도 부근에 나타나며, 비가 많아 빽빽한 열대 우림이 자라는 곳도 있어요. 사람들은 습기와 해충을 피하려고 땅에서 띄워 짓는 고상 가옥을 짓기도 해요.\n예: 동남아시아, 아마존강 유역이 열대 기후 지역이에요."),
        ce(.middle, "우리와 다른 기후, 다른 생활", ["건조 기후", "사막 기후", "스텝 기후"], "건조 기후는 비가 적게 와서 증발량이 강수량보다 많은 기후예요. 연 강수량이 대략 250mm 미만인 곳은 사막 기후, 그보다 조금 많아 짧은 풀이 자라는 곳은 스텝 기후라고 해요. 오아시스 주변에서 농사를 짓거나 가축을 데리고 이동하는 유목 생활을 하기도 해요.\n예: 사막 지역 사람들은 강한 햇빛과 모래바람을 막으려고 온몸을 감싸는 헐렁한 옷을 입어요."),
        ce(.middle, "우리와 다른 기후, 다른 생활", ["온대 기후", "지중해성 기후", "서안 해양성 기후"], "온대 기후는 가장 추운 달의 평균 기온이 영하 3℃ 이상 18℃ 미만인, 사계절이 비교적 뚜렷하고 사람이 살기 좋은 기후예요. 여름이 덥고 건조한 지중해성 기후, 1년 내내 온화하고 비가 고른 서안 해양성 기후, 계절에 따라 기온과 강수 차이가 큰 온대 계절풍 기후 등이 있어요.\n예: 이탈리아의 올리브·포도 재배는 지중해성 기후를 이용한 거예요."),
        ce(.middle, "우리와 다른 기후, 다른 생활", ["냉대 기후", "타이가"], "냉대 기후는 겨울이 길고 매우 추우며 여름은 짧지만 비교적 따뜻한 기후예요. 가장 추운 달 평균 기온이 영하 3℃ 미만이고, 가장 따뜻한 달은 10℃ 이상이에요. 침엽수림(타이가)이 넓게 펼쳐져 목재와 펄프 산업이 발달했어요.\n예: 러시아 시베리아와 캐나다의 넓은 지역이 냉대 기후예요."),
        ce(.middle, "우리와 다른 기후, 다른 생활", ["한대 기후", "툰드라 기후", "빙설 기후"], "한대 기후는 가장 따뜻한 달의 평균 기온도 10℃가 안 되는 매우 추운 기후예요. 짧은 여름에 땅 표면이 녹아 이끼가 자라는 툰드라 기후와 1년 내내 얼음으로 덮인 빙설 기후가 있어요. 툰드라 지역 사람들은 순록을 기르거나 사냥과 고기잡이를 하며 살아왔어요.\n예: 북극해 주변과 남극 대륙이 한대 기후 지역이에요."),

        ce(.middle, "자연으로 떠나는 여행", ["해안 지형", "곶과 만"], "해안 지형은 파도, 조류, 바람 등의 작용으로 바닷가에 만들어진 지형이에요. 바다 쪽으로 튀어나온 곶에서는 파도의 침식으로 해식애(절벽)와 해식 동굴이 생기고, 육지 쪽으로 들어간 만에서는 모래가 쌓여 모래사장(사빈)이 생겨요. 밀물과 썰물의 차가 큰 서해안에는 넓은 갯벌이 발달했어요.\n예: 서해안의 갯벌과 동해안의 긴 모래사장은 대표적인 해안 지형이에요."),
        ce(.middle, "자연으로 떠나는 여행", ["카르스트 지형", "석회 동굴"], "카르스트 지형은 석회암이 빗물이나 지하수에 녹아서 만들어진 지형이에요. 땅속에는 석회 동굴이, 땅 위에는 움푹 파인 돌리네 같은 지형이 생겨요. 동굴 안에서는 종유석, 석순, 석주가 자라요.\n예: 강원도 삼척의 환선굴과 중국 구이린의 탑 모양 봉우리가 카르스트 지형이에요."),
        ce(.middle, "자연으로 떠나는 여행", ["화산 지형", "주상 절리", "용암 동굴"], "화산 지형은 땅속의 마그마가 지표로 분출해 만들어진 지형이에요. 분화구, 분화구에 물이 고인 화구호, 용암이 흐르며 만든 용암 동굴, 기둥 모양으로 갈라진 주상 절리 등이 있어요. 화산 지역은 땅이 비옥하고 온천과 지열 발전을 이용할 수 있어요.\n예: 제주도의 한라산 백록담, 만장굴, 주상 절리대가 화산 지형이에요."),

        ce(.middle, "인구 변화와 인구 문제", ["인구 분포", "인구 밀도"], "인구 분포는 인구가 지역에 따라 흩어져 있는 모습이에요. 기후가 온화하고 평야가 넓으며 물을 얻기 쉬운 곳, 일자리와 교통이 발달한 곳에 인구가 많이 모여요. 반대로 너무 춥거나 건조한 곳, 험한 산지에는 인구가 적어요.\n예: 우리나라는 인구의 절반 정도가 수도권(서울·인천·경기)에 살아요."),
        ce(.middle, "인구 변화와 인구 문제", ["인구 이동", "흡인 요인", "배출 요인"], "인구 이동은 사람들이 일자리, 교육, 환경 등의 이유로 사는 곳을 옮기는 것이에요. 사람을 끌어당기는 흡인 요인과 떠나게 만드는 배출 요인이 함께 작용해요. 국내 이동과 국제 이동, 자발적 이동과 강제적 이동으로 나눌 수 있어요.\n예: 더 나은 일자리를 찾아 다른 나라로 가는 노동자, 전쟁을 피해 떠나는 난민이 있어요."),
        ce(.middle, "인구 변화와 인구 문제", ["저출산·고령화", "저출산", "고령화"], "저출산은 출생아 수가 줄어드는 현상이고, 고령화는 전체 인구 중 65세 이상 인구의 비율이 높아지는 현상이에요. 이 비율이 7% 이상이면 고령화 사회, 14% 이상이면 고령 사회, 20% 이상이면 초고령 사회라고 해요. 일할 사람이 줄고 복지 비용이 늘어나는 문제가 생겨요.\n예: 우리나라는 2024년 말 65세 이상 인구 비율이 20%를 넘어 초고령 사회가 되었어요."),
        ce(.middle, "인구 변화와 인구 문제", ["도시화", "도시화율"], "도시화는 전체 인구 가운데 도시에 사는 인구의 비율이 높아지는 현상이에요. 산업화로 도시에 일자리가 늘면 촌락 인구가 도시로 몰려 도시화가 빠르게 진행돼요. 선진국은 오랜 기간 천천히, 개발 도상국은 짧은 기간에 빠르게 도시화가 진행된 경우가 많아요.\n예: 우리나라는 1960년대 이후 산업화와 함께 도시화가 빠르게 진행되었어요."),

        ce(.middle, "자원을 둘러싼 경쟁과 갈등", ["자원의 특성", "자원의 편재성", "자원의 유한성"], "자원은 인간 생활에 쓸모 있고 기술적·경제적으로 개발할 수 있는 것을 말해요. 자원은 양이 한정된 유한성, 특정 지역에 치우쳐 있는 편재성, 기술과 경제 조건에 따라 가치가 달라지는 가변성을 가져요. 편재성 때문에 자원을 둘러싼 국가 간 경쟁과 갈등이 생기기도 해요.\n예: 석유는 서남아시아 페르시아만 주변에 많이 묻혀 있어요."),
        ce(.middle, "자원을 둘러싼 경쟁과 갈등", ["신재생 에너지", "재생 에너지"], "신재생 에너지는 태양광, 풍력, 수력, 지열, 바이오 에너지 같은 재생 에너지와 수소, 연료 전지 같은 신에너지를 함께 이르는 말이에요. 화석 연료와 달리 고갈 걱정이 적고 온실가스 배출이 적지만, 날씨에 따라 생산량이 달라지고 설치 비용이 많이 드는 단점이 있어요.\n예: 바람이 강한 해안과 산지에 풍력 발전기를 세워요."),

        ce(.middle, "개인과 사회생활", ["사회화", "재사회화"], "사회화는 개인이 사회 구성원으로 살아가는 데 필요한 언어, 지식, 가치, 행동 양식을 배우는 과정이에요. 가족, 또래 집단, 학교, 대중 매체 등이 사회화를 돕는 기관이에요. 사회화는 평생에 걸쳐 일어나며, 새로운 환경에 맞게 다시 배우는 재사회화도 있어요.\n예: 아이가 가족에게서 인사하는 법을 배우는 것, 노인이 스마트폰 사용법을 배우는 것 모두 사회화예요."),
        ce(.middle, "개인과 사회생활", ["사회적 지위", "귀속 지위", "성취 지위"], "사회적 지위는 개인이 집단이나 사회 안에서 차지하는 위치예요. 태어나면서 저절로 갖게 되는 귀속 지위와 자신의 노력으로 얻는 성취 지위가 있어요. 지위에 따라 기대되는 행동을 역할이라고 하고, 여러 역할이 동시에 요구되어 갈등하는 것을 역할 갈등이라고 해요.\n예: 딸, 아들은 귀속 지위이고, 학생회장, 의사는 성취 지위예요."),
        ce(.middle, "개인과 사회생활", ["문화의 특징", "문화의 속성"], "문화는 한 사회 구성원들이 공유하는 생활 양식이에요. 문화는 구성원이 함께 나누는 공유성, 태어난 뒤 배워서 익히는 학습성, 세대를 이어 쌓여 가는 축적성, 시간이 지나며 바뀌는 변동성, 각 부분이 서로 연결된 총체성을 가져요.\n예: 스마트폰이 보급되면서 소통, 쇼핑, 놀이 문화가 함께 바뀐 것은 총체성을 보여 줘요."),
        ce(.middle, "개인과 사회생활", ["문화 상대주의", "문화 상대주의적 태도"], "문화 상대주의는 각 문화를 그 사회의 자연환경과 역사적·사회적 배경 속에서 이해하려는 태도예요. 문화의 다양성을 존중하게 해 주지만, 인간의 존엄성을 해치는 관습까지 인정하는 극단적 문화 상대주의는 경계해야 해요.\n예: 인도의 많은 힌두교도가 소고기를 먹지 않는 것을 그 지역의 종교와 농경 생활 속에서 이해하는 태도예요."),
        ce(.middle, "개인과 사회생활", ["자문화 중심주의", "문화 사대주의"], "자문화 중심주의는 자기 문화만 우수하다고 여기고 다른 문화를 낮게 평가하는 태도예요. 집단의 결속을 높일 수 있지만 다른 문화를 무시해 갈등을 일으킬 수 있어요. 반대로 다른 사회의 문화를 무조건 높이 보고 자기 문화를 낮추는 태도는 문화 사대주의라고 해요.\n예: 다른 나라의 음식 문화를 이상하고 미개하다고 깎아내리는 것이 자문화 중심주의예요."),

        ce(.middle, "정치 과정과 시민 참여", ["정치 과정", "투입과 산출"], "정치 과정은 사회의 다양한 요구가 정책으로 결정되고 실행되는 과정이에요. 시민, 이익 집단, 시민 단체, 언론, 정당 등이 의견을 모아 국회나 정부에 전달하면(투입), 정부가 이를 검토해 정책을 만들고(산출), 그 결과가 다시 새로운 요구로 이어져요(환류).\n예: 학교 앞 횡단보도 설치 요구가 지방 자치 단체에 전달되어 실제로 설치되는 과정이에요."),
        ce(.middle, "정치 과정과 시민 참여", ["이익 집단", "압력 단체"], "이익 집단은 같은 이해관계를 가진 사람들이 자신들의 특수한 이익을 실현하려고 만든 집단이에요. 정권 획득을 목표로 하지 않고, 정부나 정당에 영향력을 행사해 정책 결정에 자신들의 의견을 반영하려 해요.\n예: 의사 단체, 변호사 단체, 노동조합, 경영자 단체 등이 이익 집단이에요."),
        ce(.middle, "정치 과정과 시민 참여", ["시민 단체", "비영리 민간단체"], "시민 단체는 시민들이 자발적으로 모여 사회 전체의 공익을 위해 활동하는 단체예요. 정부 정책을 감시하고 비판하거나 환경, 인권, 소비자 보호 같은 문제에 대한 여론을 만들어요. 특정 집단의 이익보다 공익을 추구한다는 점에서 이익 집단과 달라요.\n예: 환경 단체가 하천 오염 문제를 알리는 캠페인을 하는 거예요."),

        ce(.middle, "인권과 헌법", ["자유권", "소극적 권리"], "자유권은 국가로부터 간섭받지 않고 자유롭게 생활할 수 있는 권리예요. 가장 오래된 기본권으로 '소극적 권리'라고도 해요. 신체의 자유, 거주·이전의 자유, 종교의 자유, 언론·출판·집회·결사의 자유 등이 있어요.\n예: 자신이 믿고 싶은 종교를 자유롭게 선택하는 것은 자유권이에요."),
        ce(.middle, "인권과 헌법", ["평등권", "차별 금지"], "평등권은 성별, 종교, 사회적 신분 등에 따라 부당하게 차별받지 않을 권리예요. 다른 기본권을 보장하는 기초가 되는 권리이고, 모든 사람을 무조건 똑같이 대하는 것이 아니라 합리적인 이유가 있는 차별은 인정하는 상대적 평등을 추구해요.\n예: 장애인 의무 고용 제도는 실질적 평등을 위한 거예요."),
        ce(.middle, "인권과 헌법", ["참정권", "선거권", "피선거권"], "참정권은 국민이 나라의 정치에 참여할 수 있는 권리예요. 선거에서 투표하는 선거권, 선거에 나가는 피선거권, 공무원이 될 수 있는 공무 담임권, 중요한 정책에 찬반을 표시하는 국민 투표권이 있어요.\n예: 만 18세 이상 국민이 대통령 선거에서 투표하는 것이 참정권 행사예요."),
        ce(.middle, "인권과 헌법", ["사회권", "생존권"], "사회권은 인간다운 생활을 위해 국가에 적극적인 보호와 지원을 요구할 수 있는 권리예요. 1919년 독일 바이마르 헌법에서 처음 규정된 비교적 새로운 기본권으로, 교육을 받을 권리, 근로의 권리, 환경권, 인간다운 생활을 할 권리 등이 있어요.\n예: 국가가 생활이 어려운 사람에게 기초 생활비를 지원하는 것은 사회권 보장이에요."),
        ce(.middle, "인권과 헌법", ["청구권", "재판 청구권", "청원권"], "청구권은 기본권이 침해되었을 때 국가에 일정한 행위를 요구할 수 있는 권리예요. 다른 기본권을 보장하기 위한 수단적 권리라고 해요. 청원권, 재판 청구권, 국가 배상 청구권, 형사 보상 청구권 등이 있어요.\n예: 억울하게 구속되었다가 무죄 판결을 받은 사람이 국가에 보상을 요구하는 것이 형사 보상 청구권이에요."),
        ce(.middle, "인권과 헌법", ["기본권의 제한", "기본권 제한의 한계"], "기본권도 무제한으로 보장되는 것은 아니에요. 헌법 제37조 제2항에 따라 국가 안전 보장, 질서 유지, 공공복리를 위해 꼭 필요한 경우에만 국회가 만든 법률로 제한할 수 있어요. 그러나 제한하더라도 자유와 권리의 본질적인 내용은 침해할 수 없어요.\n예: 감염병 확산을 막기 위해 법률에 따라 일정 기간 격리하는 것이 기본권 제한의 예예요."),
        ce(.middle, "인권과 헌법", ["법의 종류", "공법·사법·사회법"], "법은 다루는 관계에 따라 공법, 사법, 사회법으로 나눌 수 있어요. 공법은 국가와 개인, 국가 기관 사이의 관계(헌법, 형법, 행정법 등), 사법은 개인과 개인 사이의 관계(민법, 상법 등)를 다뤄요. 사회법은 사회적 약자를 보호하려고 생겨난 법으로 노동법, 사회 보장법, 경제법이 있어요.\n예: 물건을 사고파는 계약 문제는 민법, 범죄 처벌은 형법이 다뤄요."),
        ce(.middle, "인권과 헌법", ["재판의 종류", "민사 재판", "형사 재판"], "민사 재판은 개인 사이의 재산이나 권리 다툼을, 형사 재판은 범죄를 저지른 사람의 유죄 여부와 형벌을 결정해요. 이 밖에 행정 기관의 처분을 다투는 행정 재판, 헌법 문제를 다루는 헌법 재판 등이 있어요. 우리나라는 원칙적으로 세 번까지 재판받을 수 있는 3심제를 운영해요.\n예: 빌려준 돈을 돌려받으려는 소송은 민사 재판이에요."),

        ce(.middle, "시장 경제와 가격", ["기회비용", "매몰 비용"], "기회비용은 어떤 것을 선택했을 때 포기한 대안들 가운데 가장 가치가 큰 것의 가치예요. 선택에 따른 편익이 기회비용보다 클 때 합리적인 선택이라고 할 수 있어요. 이미 써 버려 되돌릴 수 없는 매몰 비용은 선택할 때 고려하지 않아야 해요.\n예: 주말에 아르바이트 대신 영화를 봤다면, 포기한 아르바이트 수입도 기회비용에 포함돼요."),
        ce(.middle, "시장 경제와 가격", ["시장 경제 체제", "시장 경제", "계획 경제"], "시장 경제 체제는 무엇을, 어떻게, 누구를 위해 생산할지를 시장 가격에 따라 해결하는 경제 체제예요. 사유 재산을 인정하고 자유로운 경쟁과 이윤 추구를 보장해요. 정부의 계획과 명령으로 해결하는 방식은 계획 경제 체제이며, 오늘날 대부분의 나라는 두 요소가 섞인 혼합 경제 체제를 운영해요.\n예: 아이스크림 가격이 수요와 공급에 따라 정해지는 것이 시장 경제의 모습이에요."),
        ce(.middle, "시장 경제와 가격", ["수요 법칙", "수요", "수요량"], "수요는 일정 기간 동안 상품을 사려고 하는 욕구이고, 실제로 사려는 양을 수요량이라고 해요. 다른 조건이 같을 때 가격이 오르면 수요량이 줄고, 가격이 내리면 수요량이 늘어나는데, 이를 수요 법칙이라고 해요. 그래서 수요 곡선은 오른쪽 아래로 내려가는 모양이에요.\n예: 딸기 값이 비싸지면 사람들이 딸기를 덜 사요."),
        ce(.middle, "시장 경제와 가격", ["공급 법칙", "공급", "공급량"], "공급은 일정 기간 동안 상품을 팔려고 하는 욕구이고, 실제로 팔려는 양을 공급량이라고 해요. 다른 조건이 같을 때 가격이 오르면 공급량이 늘고, 가격이 내리면 공급량이 줄어드는데, 이를 공급 법칙이라고 해요. 그래서 공급 곡선은 오른쪽 위로 올라가는 모양이에요.\n예: 배추 값이 오르면 농민들이 배추를 더 많이 팔려고 해요."),
        ce(.middle, "시장 경제와 가격", ["균형 가격", "시장 가격", "초과 수요"], "균형 가격은 수요량과 공급량이 같아지는 지점에서 결정되는 가격이에요. 가격이 균형보다 높으면 물건이 남는 초과 공급이, 낮으면 물건이 모자라는 초과 수요가 생기고, 그 결과 가격이 다시 균형 쪽으로 움직여요.\n예: 공연 표가 너무 싸서 사려는 사람이 넘치면(초과 수요) 가격이 오르는 압력이 생겨요."),

        ce(.middle, "한국사의 흐름", ["구석기 시대", "뗀석기"], "구석기 시대는 돌을 깨뜨리거나 떼어 내서 만든 뗀석기를 사용한 시대예요. 사람들은 사냥, 고기잡이, 열매 채집으로 먹을 것을 구했고, 먹을거리를 찾아 이동하며 동굴이나 강가의 막집에서 살았어요. 한반도에는 약 70만 년 전부터 사람이 살기 시작한 것으로 보고 있어요.\n예: 경기도 연천 전곡리에서 출토된 주먹도끼가 대표적인 구석기 유물이에요."),
        ce(.middle, "한국사의 흐름", ["신석기 시대", "간석기", "빗살무늬 토기"], "신석기 시대는 돌을 갈아서 만든 간석기와 토기를 사용한 시대로, 한반도에서는 약 1만 년 전부터 시작되었어요. 농경과 목축이 시작되면서 강가나 바닷가에 움집을 짓고 한곳에 머물러 사는 정착 생활을 했어요. 빗살무늬 토기에 곡식을 저장했어요.\n예: 서울 암사동 유적에서 움집 터와 빗살무늬 토기가 발견되었어요."),
        ce(.middle, "한국사의 흐름", ["청동기 시대", "고인돌"], "청동기 시대는 구리와 주석을 섞은 청동으로 무기와 장신구를 만든 시대예요. 벼농사가 시작되고 생산물이 늘면서 재산의 차이가 생겨 계급이 나타났어요. 부족을 이끄는 군장이 등장했고, 이 시기에 고조선이 세워졌어요.\n예: 지배층의 무덤인 고인돌과 비파형 동검, 민무늬 토기가 청동기 시대의 대표 유적·유물이에요."),
        ce(.middle, "한국사의 흐름", ["무신 정권", "무신 정변"], "무신 정권은 1170년 무신 정변 이후 약 100년 동안 무신들이 고려의 정치를 장악한 시기예요. 문신에 비해 차별받던 무신들이 정권을 잡았고, 최충헌 이후 최씨 가문이 4대 60여 년간 권력을 이어 갔어요. 이 시기에 몽골이 침입하자 도읍을 강화도로 옮겨 맞서기도 했어요.\n예: 무신 집권기에 망이·망소이의 난, 만적의 난 같은 하층민의 봉기가 일어났어요."),
        ce(.middle, "한국사의 흐름", ["실학", "실학자", "정약용"], "실학은 조선 후기에 성리학이 현실 문제를 해결하지 못한다고 비판하며 등장한, 실제 생활에 도움이 되는 학문이에요. 토지 제도를 개혁해 농민 생활을 안정시키자는 주장(유형원, 이익, 정약용)과 상공업을 발전시키고 청의 문물을 받아들이자는 주장(박지원, 박제가)이 있었어요.\n예: 정약용은 거중기를 설계해 수원 화성 건설에 도움을 주었어요."),

        ce(.middle, "세계사의 흐름", ["세계 4대 문명", "고대 문명"], "세계 4대 문명은 큰 강 유역에서 발생한 메소포타미아, 이집트, 인더스, 중국(황허) 문명을 말해요. 기원전 3500년 무렵 메소포타미아를 시작으로, 물이 풍부하고 땅이 기름진 곳에서 농사가 발달하며 청동기와 문자를 사용하는 도시와 국가가 생겨났어요.\n예: 메소포타미아의 쐐기 문자, 이집트의 피라미드와 상형 문자가 유명해요."),
        ce(.middle, "세계사의 흐름", ["아테네 민주 정치", "고대 아테네 민주주의"], "고대 그리스의 도시 국가 아테네에서는 기원전 5세기 페리클레스 시기에 민주 정치가 꽃피었어요. 성인 남성 시민이 민회에 직접 참여해 나라의 중요한 일을 결정하는 직접 민주 정치였어요. 하지만 여성, 노예, 외국인은 정치에 참여할 수 없다는 한계가 있었어요.\n예: 추첨으로 공직자를 뽑았고, 위험 인물을 투표로 추방하는 도편 추방제도 있었어요."),
        ce(.middle, "세계사의 흐름", ["르네상스", "문예 부흥"], "르네상스는 14세기 무렵 이탈리아에서 시작되어 유럽으로 퍼진 문화 운동으로, '다시 태어남'이라는 뜻이에요. 고대 그리스·로마 문화를 되살려 신 중심의 생각에서 벗어나 인간을 중시하는 인문주의를 강조했어요.\n예: 레오나르도 다빈치의 「모나리자」, 미켈란젤로의 「다비드」가 대표적인 르네상스 작품이에요."),
        ce(.middle, "세계사의 흐름", ["종교 개혁", "루터", "95개조 반박문"], "종교 개혁은 16세기 유럽에서 로마 가톨릭교회의 부패를 비판하며 일어난 개혁 운동이에요. 1517년 독일의 루터가 면벌부 판매를 비판하는 95개조 반박문을 발표하면서 시작되었고, 칼뱅 등이 뒤를 이었어요. 그 결과 가톨릭에서 갈라져 나온 개신교(프로테스탄트)가 생겼어요.\n예: 루터는 성경을 독일어로 번역해 사람들이 직접 읽을 수 있게 했어요."),
        ce(.middle, "세계사의 흐름", ["산업 혁명", "증기 기관"], "산업 혁명은 18세기 후반 영국에서 시작된, 기계를 이용한 생산 방식으로의 큰 변화예요. 증기 기관이 개량되고 면직물 공업에 기계가 쓰이며 공장제 기계 공업이 발달했어요. 생산량은 크게 늘었지만 도시 노동자의 열악한 노동 환경과 환경 오염 같은 문제도 생겼어요.\n예: 제임스 와트가 개량한 증기 기관은 증기 기관차와 증기선의 등장으로 이어졌어요."),

        ce(.middle, "사회·공동체와의 관계", ["도덕적 성찰", "성찰"], "도덕적 성찰은 자신의 생각과 행동이 도덕적으로 옳았는지 스스로 돌아보고 반성하는 것이에요. 성찰을 통해 잘못을 고치고 더 나은 사람이 되기 위해 노력할 수 있어요. 일기 쓰기, 좌우명 정하기, 존경하는 인물의 삶 본받기 등의 방법이 있어요.\n예: 공자의 제자 증자는 하루에 세 번 자신을 돌아본다는 '일일삼성'을 실천했어요."),
        ce(.middle, "사회·공동체와의 관계", ["세계 시민", "세계 시민 의식"], "세계 시민은 자기 나라뿐 아니라 인류 전체를 공동체로 여기고 지구촌 문제에 관심을 가지며 해결에 참여하는 사람이에요. 빈곤, 기후 위기, 난민 같은 문제에 책임감을 느끼고 다른 문화를 존중하는 태도가 필요해요.\n예: 공정 무역 제품을 사거나 국제 구호 단체에 기부하는 것은 세계 시민으로서의 실천이에요."),
        ce(.middle, "사회·공동체와의 관계", ["적극적 평화", "소극적 평화", "평화"], "평화학자 요한 갈퉁은 평화를 두 가지로 나누었어요. 소극적 평화는 전쟁, 테러 같은 직접적 폭력이 없는 상태이고, 적극적 평화는 빈곤, 차별, 억압 같은 구조적·문화적 폭력까지 사라진 상태예요. 진정한 평화를 위해서는 적극적 평화를 추구해야 한다고 보았어요.\n예: 전쟁이 없어도 굶주림과 차별이 심하다면 적극적 평화는 이루어지지 않은 거예요."),
        ce(.middle, "사회·공동체와의 관계", ["통일 윤리 의식", "통일 한국의 미래"], "통일 윤리 의식은 남북통일을 도덕적 관점에서 바라보고 평화적으로 이루려는 태도예요. 통일은 평화적인 방법으로, 민족의 동질성을 회복하며, 자유와 인권 같은 보편적 가치를 실현하는 방향으로 이루어져야 해요. 통일 비용뿐 아니라 분단으로 생기는 비용과 통일 이후의 편익도 함께 생각해야 해요.\n예: 남북의 다른 언어 습관과 생활 문화를 이해하려는 노력도 통일 준비예요."),

        // MARK: - 고등학교

        ce(.high, "세계화와 평화", ["세계화", "다국적 기업"], "세계화는 교통·통신이 발달하고 국가 간 교류가 늘면서 세계가 하나의 생활권으로 통합되어 가는 현상이에요. 상품, 자본, 노동, 정보, 문화가 국경을 넘어 활발히 오가요. 경제 성장과 문화 교류의 기회가 늘어나는 반면, 국가 간 빈부 격차나 문화의 획일화 같은 문제도 생길 수 있어요.\n예: 다국적 기업이 본사는 선진국에, 생산 공장은 임금이 낮은 나라에 두는 것도 세계화의 모습이에요."),
        ce(.high, "세계화와 평화", ["지속 가능한 발전", "지속가능발전", "SDGs"], "지속 가능한 발전은 미래 세대가 자신의 필요를 충족할 능력을 해치지 않으면서 현재 세대의 필요를 충족하는 발전이에요. 1987년 유엔 세계 환경 개발 위원회의 보고서 「우리 공동의 미래」로 널리 알려졌어요. 경제 성장, 사회 통합, 환경 보전의 균형을 추구해요.\n예: 국제 연합은 2015년에 2030년까지 이룰 17개의 지속 가능 발전 목표(SDGs)를 채택했어요."),

        ce(.high, "전근대 한국사의 이해", ["과거 제도", "과거제"], "과거 제도는 시험을 통해 능력 있는 관리를 뽑는 제도예요. 우리나라에서는 고려 광종 때인 958년 쌍기의 건의로 처음 실시되었어요. 조선에서는 문과, 무과, 잡과로 나누어 치렀고, 1894년 갑오개혁 때 폐지되었어요.\n예: 조선 시대 양반들은 문과에 합격해 관리가 되는 것을 큰 목표로 삼았어요."),
        ce(.high, "전근대 한국사의 이해", ["대동법", "공납 개혁"], "대동법은 집집마다 지역 특산물을 바치던 공납을 토지 면적에 따라 쌀, 옷감, 동전 등으로 내게 한 조선 후기의 세금 제도예요. 1608년 광해군 때 경기도에서 처음 시행되어 약 100년에 걸쳐 전국으로 확대되었어요. 땅이 없거나 적은 농민의 부담이 줄었고, 관청에 물품을 대는 공인이 등장해 상업이 발달했어요.\n예: 방납의 폐단으로 고통받던 농민들의 부담을 덜어 주었어요."),
        ce(.high, "전근대 한국사의 이해", ["탕평책", "탕평 정치"], "탕평책은 붕당 간의 대립을 누그러뜨리기 위해 여러 붕당의 인재를 고르게 등용한 조선 후기 정책이에요. 영조는 탕평비를 세우고 균역법을 실시했으며, 정조는 규장각을 설치하고 수원 화성을 건설하며 개혁을 이어 갔어요.\n예: 영조가 성균관 앞에 세운 탕평비에는 붕당을 짓지 말라는 뜻이 담겨 있어요."),

        ce(.high, "근대 국민 국가 수립 운동", ["강화도 조약", "조일 수호 조규"], "강화도 조약은 1876년 조선이 일본과 맺은 우리나라 최초의 근대적 조약이에요. 운요호 사건을 구실로 일본이 강요해 맺어졌으며, 부산 외 두 항구(원산, 인천)를 열고 일본에 해안 측량권과 치외 법권(영사 재판권)을 인정한 불평등 조약이었어요.\n예: 이 조약으로 조선은 문호를 개방하고 개항기에 들어섰어요."),
        ce(.high, "근대 국민 국가 수립 운동", ["갑신정변", "김옥균", "급진 개화파"], "갑신정변은 1884년 김옥균, 박영효 등 급진 개화파가 우정총국 개국 축하연을 기회로 일으킨 정변이에요. 청의 간섭에서 벗어나 일본의 메이지 유신을 본보기로 근대 국가를 세우려 했지만, 청군의 개입으로 3일 만에 실패했어요.\n예: 개화당 정부는 14개조 정강에서 문벌 폐지와 인민 평등권 등을 내세웠어요."),
        ce(.high, "근대 국민 국가 수립 운동", ["동학 농민 운동", "전봉준", "동학 농민 혁명"], "동학 농민 운동은 1894년 전봉준 등이 이끈 농민들이 탐관오리의 수탈과 외세의 침략에 맞서 일으킨 운동이에요. 고부 군수 조병갑의 횡포에 맞선 고부 농민 봉기에서 시작해 전주성을 점령했고, 전주 화약 이후 집강소를 설치해 개혁을 추진했어요. 일본군에 맞서 다시 일어났으나 우금치 전투에서 패배했어요.\n예: 농민군은 신분제 폐지 등 반봉건·반외세 개혁을 요구했어요."),
        ce(.high, "근대 국민 국가 수립 운동", ["갑오개혁", "군국기무처"], "갑오개혁은 1894년부터 1895년까지 군국기무처 등을 중심으로 추진된 근대적 개혁이에요. 신분제와 과거제를 폐지하고, 왕실 사무와 국정 사무를 분리했으며, 세금을 돈으로 내게 하는 등 정치·경제·사회 전반을 바꾸었어요. 일본의 간섭 아래 추진되었다는 한계도 있어요.\n예: 갑오개혁으로 양반과 상민을 구분하는 신분제가 법적으로 폐지되었어요."),
        ce(.high, "근대 국민 국가 수립 운동", ["독립 협회", "만민 공동회"], "독립 협회는 1896년 서재필 등이 중심이 되어 세운 단체로, 자주 국권, 자유 민권, 자강 개혁을 내세웠어요. 독립문을 세우고, 만민 공동회와 관민 공동회를 열어 민중의 정치 참여를 이끌었어요. 1898년 정부의 탄압으로 해산되었어요.\n예: 서재필이 1896년에 창간한 『독립신문』은 최초의 민간 신문이자 한글 신문이에요."),
        ce(.high, "근대 국민 국가 수립 운동", ["을사늑약", "을사조약"], "을사늑약은 1905년 일본이 강압적으로 체결한 조약으로, 대한 제국의 외교권을 빼앗고 통감부를 설치했어요. 고종은 이 조약이 무효임을 알리려 1907년 헤이그 만국 평화 회의에 특사를 보냈지만, 일본은 이를 구실로 고종을 강제로 물러나게 했어요.\n예: 장지연은 「시일야방성대곡」을 『황성신문』에 실어 을사늑약을 비판했어요."),

        ce(.high, "일제 식민지 지배와 민족 운동", ["무단 통치", "헌병 경찰 통치"], "무단 통치는 1910년대 일제가 헌병 경찰을 앞세워 우리 민족을 강압적으로 다스린 방식이에요. 조선 총독부를 설치하고, 언론·집회·결사의 자유를 빼앗았으며, 관리와 교사까지 제복을 입고 칼을 차게 했어요. 토지 조사 사업으로 많은 토지를 빼앗기도 했어요.\n예: 헌병 경찰은 재판 없이 한국인에게 태형을 가할 수 있었어요."),
        ce(.high, "일제 식민지 지배와 민족 운동", ["3·1 운동", "삼일 운동"], "3·1 운동은 1919년 3월 1일 민족 대표 33인의 독립 선언을 계기로 전국과 해외로 퍼진 대규모 독립운동이에요. 신분, 종교, 지역을 넘어 많은 사람이 비폭력 만세 시위에 참여했어요. 이를 계기로 대한민국 임시 정부가 수립되었고, 일제는 통치 방식을 이른바 문화 통치로 바꾸었어요.\n예: 3·1 운동은 중국의 5·4 운동 등 다른 나라의 민족 운동에도 영향을 주었어요."),
        ce(.high, "일제 식민지 지배와 민족 운동", ["대한민국 임시 정부", "임시 정부", "한국광복군"], "대한민국 임시 정부는 3·1 운동 이후 1919년 4월 중국 상하이에서 수립된, 우리나라 최초의 민주 공화제 정부예요. 연통제와 교통국으로 국내와 연락했고, 외교 활동과 독립 자금 모금을 펼쳤어요. 1940년에는 충칭에서 한국광복군을 창설해 무장 투쟁을 준비했어요.\n예: 대한민국 헌법 전문은 3·1 운동으로 건립된 임시 정부의 법통을 계승한다고 밝혀요."),
        ce(.high, "일제 식민지 지배와 민족 운동", ["민족 말살 통치", "황국 신민화 정책", "창씨개명"], "민족 말살 통치는 1930년대 후반부터 일제가 침략 전쟁을 확대하며 우리 민족의 정체성을 없애려 한 정책이에요. 황국 신민 서사 암송과 신사 참배를 강요하고, 우리말 사용을 억압했으며, 성과 이름을 일본식으로 바꾸게 하는 창씨개명을 강요했어요. 징용, 징병 등으로 사람과 물자도 강제로 빼앗았어요.\n예: 이 시기에 일본군 '위안부'로 강제 동원되는 피해가 일어났어요."),

        ce(.high, "대한민국의 발전", ["4·19 혁명", "3·15 부정 선거"], "4·19 혁명은 1960년 이승만 정부의 3·15 부정 선거에 맞서 학생과 시민이 일으킨 민주 혁명이에요. 마산에서 김주열 학생의 시신이 발견되면서 시위가 전국으로 퍼졌고, 결국 이승만 대통령이 물러났어요. 이후 의원 내각제의 장면 정부가 들어섰어요.\n예: 4·19 혁명은 학생과 시민의 힘으로 독재 정권을 물러나게 한 사례로 평가받아요."),
        ce(.high, "대한민국의 발전", ["5·18 민주화 운동", "광주 민주화 운동"], "5·18 민주화 운동은 1980년 5월 광주에서 신군부의 비상계엄 확대와 계엄군의 폭력적 진압에 맞서 시민들이 일으킨 민주화 운동이에요. 많은 시민이 희생되었지만 이후 우리나라 민주화 운동의 큰 원동력이 되었어요.\n예: 5·18 민주화 운동 기록물은 2011년 유네스코 세계 기록 유산으로 등재되었어요."),
        ce(.high, "대한민국의 발전", ["6월 민주 항쟁", "6·29 민주화 선언"], "6월 민주 항쟁은 1987년 6월 전두환 정부의 독재와 대통령 간선제 유지(4·13 호헌 조치)에 맞서 전국에서 일어난 민주화 운동이에요. 박종철 고문치사 사건과 이한열 학생이 최루탄에 맞아 쓰러진 일로 시위가 확산되었어요. 그 결과 6·29 민주화 선언이 발표되고 대통령 직선제 개헌이 이루어졌어요.\n예: 현행 헌법(제9차 개헌)은 6월 민주 항쟁의 결과로 만들어졌어요."),
        ce(.high, "대한민국의 발전", ["외환 위기", "IMF 외환 위기"], "외환 위기는 1997년 우리나라가 외국에 갚을 외화가 바닥나 국제 통화 기금(IMF)에 구제 금융을 요청한 사건이에요. 많은 기업이 무너지고 실업자가 크게 늘었어요. 국민들의 금 모으기 운동과 기업·금융 구조 조정 등을 거쳐 2001년에 지원받은 자금을 모두 갚았어요.\n예: 외환 위기 이후 비정규직이 늘어나는 등 고용 구조가 크게 바뀌었어요."),

        ce(.high, "제국주의와 두 차례 세계 대전", ["시민 혁명", "프랑스 혁명", "명예혁명"], "시민 혁명은 17~18세기 유럽과 아메리카에서 시민 계급이 절대 왕정에 맞서 자유와 평등, 국민 주권을 실현하려 한 혁명이에요. 영국의 명예혁명(1688), 미국 혁명(1776년 독립 선언), 프랑스 혁명(1789)이 대표적이에요. 이 혁명들로 입헌주의와 민주주의의 기초가 마련되었어요.\n예: 프랑스 혁명 때 발표된 「인간과 시민의 권리 선언」은 자유와 평등을 내세웠어요."),
        ce(.high, "제국주의와 두 차례 세계 대전", ["제국주의", "식민지 쟁탈"], "제국주의는 19세기 후반 서구 열강이 산업 혁명으로 커진 경제력과 군사력을 바탕으로 아시아, 아프리카 등을 식민지로 삼아 지배한 정책이나 사상이에요. 원료 공급지와 상품 시장을 확보하려는 목적이 컸고, 사회 진화론과 인종주의로 침략을 정당화했어요.\n예: 20세기 초 아프리카는 에티오피아와 라이베리아를 빼고 대부분 유럽의 식민지가 되었어요."),
        ce(.high, "제국주의와 두 차례 세계 대전", ["메이지 유신", "일본의 근대화"], "메이지 유신은 1868년 일본에서 에도 막부가 무너지고 천황 중심의 정부가 세워지면서 추진된 근대화 개혁이에요. 서양의 기술과 제도를 적극 받아들여 신분제를 개편하고 징병제와 근대 교육을 실시했으며 산업을 키웠어요. 이후 일본은 제국주의 국가로 성장해 주변 나라를 침략했어요.\n예: 1889년 일본은 메이지 헌법(대일본 제국 헌법)을 공포해 입헌 군주제를 마련했어요."),
        ce(.high, "제국주의와 두 차례 세계 대전", ["제1차 세계 대전", "1차 대전", "사라예보 사건"], "제1차 세계 대전은 1914년부터 1918년까지 연합국(영국, 프랑스, 러시아 등)과 동맹국(독일, 오스트리아-헝가리 등) 사이에 벌어진 전쟁이에요. 사라예보 사건이 계기가 되었고, 비행기·탱크·독가스 같은 신무기가 쓰인 총력전이었어요. 전쟁 후 베르사유 체제가 성립하고 국제 연맹이 만들어졌어요.\n예: 미국 윌슨 대통령이 내세운 민족 자결주의는 식민지 민족 운동에 영향을 주었어요."),
        ce(.high, "제국주의와 두 차례 세계 대전", ["제2차 세계 대전", "2차 대전", "홀로코스트"], "제2차 세계 대전은 1939년 독일의 폴란드 침공으로 시작되어 1945년까지 이어진 전쟁이에요. 독일, 이탈리아, 일본의 추축국과 영국, 미국, 소련, 중국 등의 연합국이 싸웠어요. 나치 독일의 유대인 대학살(홀로코스트) 같은 참혹한 일이 있었고, 1945년 일본의 항복으로 끝났어요.\n예: 전쟁이 끝난 뒤 평화를 지키기 위해 1945년 국제 연합이 창설되었어요."),
        ce(.high, "제국주의와 두 차례 세계 대전", ["냉전", "냉전 체제"], "냉전은 제2차 세계 대전 이후 미국 중심의 자본주의 진영과 소련 중심의 공산주의 진영이 직접 전쟁은 피하면서 대립한 상황이에요. 군비 경쟁과 우주 개발 경쟁이 벌어졌고, 한국 전쟁, 베트남 전쟁처럼 실제 전쟁이 일어난 지역도 있었어요. 1989년 베를린 장벽 붕괴와 1991년 소련 해체로 사실상 끝났어요.\n예: 독일은 냉전 속에 동서로 분단되었다가 1990년에 통일되었어요."),

        ce(.high, "국토 인식과 지리 정보", ["영역", "영토·영해·영공"], "영역은 한 나라의 주권이 미치는 범위로, 영토, 영해, 영공으로 이루어져요. 영해는 보통 기선으로부터 12해리까지이고, 영공은 영토와 영해의 수직 상공이에요. 우리나라 영토는 헌법에 따라 한반도와 그 부속 도서예요.\n예: 섬이 많은 서해안과 남해안은 바깥쪽 섬을 이은 직선 기선을, 해안선이 단조로운 동해안은 대부분 썰물 때의 해안선인 통상 기선을 기준으로 영해를 정해요."),
        ce(.high, "국토 인식과 지리 정보", ["배타적 경제 수역", "EEZ"], "배타적 경제 수역(EEZ)은 영해 기선으로부터 200해리까지의 바다 가운데 영해를 뺀 수역이에요. 연안국은 이 수역의 어업 자원과 해저 광물 자원을 탐사·개발할 경제적 권리를 가져요. 다른 나라 배도 지나갈 수 있고, 이웃 나라와 겹치는 곳은 협정을 맺어 관리해요.\n예: 우리나라는 중국, 일본과 어업 협정을 맺어 함께 관리하는 수역을 정했어요."),
        ce(.high, "국토 인식과 지리 정보", ["독도", "독도의 영토 주권"], "독도는 경상북도 울릉군에 속한 우리나라 가장 동쪽 끝의 섬으로, 동도와 서도 및 여러 바위섬으로 이루어져 있어요. 『세종실록지리지』 등 옛 문헌에도 기록되어 있는 우리 고유의 영토예요. 주변 바다는 난류와 한류가 만나 수산 자원이 풍부해요.\n예: 독도는 화산 활동으로 만들어진 섬으로, 섬 전체가 천연기념물로 지정되어 있어요."),
        ce(.high, "국토 인식과 지리 정보", ["지리 정보 시스템", "GIS"], "지리 정보 시스템(GIS)은 다양한 지리 정보를 컴퓨터에 입력·저장하고 분석해 필요한 정보를 얻는 시스템이에요. 여러 지도 정보를 층(레이어)으로 겹쳐 분석할 수 있어 입지 선정, 재해 예측, 도시 계획 등에 활용돼요.\n예: 인구, 교통, 땅값 지도를 겹쳐서 새 학교를 세울 알맞은 위치를 찾는 거예요."),

        ce(.high, "민주주의와 헌법", ["대통령제", "대통령 중심제"], "대통령제는 국민이 선거로 뽑은 대통령이 국가 원수이자 행정부 수반이 되는 정부 형태예요. 입법부와 행정부가 엄격히 분리되어 대통령은 임기 동안 안정적으로 정책을 추진할 수 있어요. 하지만 대통령과 의회가 대립하면 해결이 어렵고, 권력이 대통령에게 집중될 수 있다는 단점이 있어요.\n예: 미국이 대표적인 대통령제 국가예요. 우리나라는 대통령제를 기본으로 국무총리 제도 같은 의원 내각제 요소를 일부 가지고 있어요."),
        ce(.high, "민주주의와 헌법", ["의원 내각제", "의원내각제", "내각 책임제"], "의원 내각제는 의회의 다수당이 내각(행정부)을 구성하고 총리가 행정부를 이끄는 정부 형태예요. 내각은 의회에 책임을 지며, 의회는 내각 불신임권을, 내각은 의회 해산권을 가져요. 입법부와 행정부가 협조하기 쉽지만, 여러 정당이 연립하면 정국이 불안정해질 수 있어요.\n예: 영국, 일본, 독일이 의원 내각제를 운영해요."),
        ce(.high, "민주주의와 헌법", ["소선거구제", "선거구 제도", "중대선거구제"], "선거구 제도는 대표를 뽑는 단위 지역에서 몇 명을 뽑느냐에 따라 나뉘어요. 소선거구제는 한 선거구에서 1명을, 중·대선거구제는 2명 이상을 뽑아요. 소선거구제는 양당제가 나타나기 쉽고 선거 관리가 쉽지만, 낙선자에게 던진 표인 사표가 많이 생기는 단점이 있어요.\n예: 우리나라 국회 의원 지역구 선거는 소선거구제로 치러요."),
        ce(.high, "민주주의와 헌법", ["비례 대표제", "정당 투표"], "비례 대표제는 정당이 얻은 득표율에 비례해 의석을 나누는 선거 제도예요. 사표를 줄이고 소수 정당도 의회에 진출할 수 있어 다양한 의견을 반영할 수 있어요. 대신 군소 정당이 많아지면 정국이 불안정해질 수 있어요.\n예: 우리나라 국회 의원 선거에서는 지역구 후보와 정당에 각각 한 표씩 투표하는 1인 2표제를 써요."),
        ce(.high, "민주주의와 헌법", ["헌법 재판소", "헌법 재판", "위헌 법률 심판"], "헌법 재판소는 헌법을 지키고 국민의 기본권을 보장하기 위해 헌법과 관련된 다툼을 심판하는 기관이에요. 9명의 재판관으로 구성되며, 위헌 법률 심판, 탄핵 심판, 정당 해산 심판, 권한 쟁의 심판, 헌법 소원 심판을 맡아요. 법률의 위헌 결정이나 탄핵 결정에는 재판관 6명 이상의 찬성이 필요해요.\n예: 헌법 재판소가 어떤 법률 조항에 위헌 결정을 내리면 그 조항은 효력을 잃어요."),

        ce(.high, "개인 생활과 법", ["계약", "계약 자유의 원칙"], "계약은 서로 대립하는 두 사람 이상의 의사 표시가 일치해 법률관계를 만드는 법률 행위예요. 청약(사겠다·팔겠다는 제안)과 승낙이 일치하면 원칙적으로 계약서 없이 말로도 성립해요. 근대 민법은 계약 자유의 원칙을 기본으로 하지만, 사회 질서에 어긋나는 계약은 무효예요.\n예: 편의점에서 물건을 골라 계산대에 올리고 점원이 계산해 주면 매매 계약이 성립해요."),
        ce(.high, "개인 생활과 법", ["미성년자의 법률 행위", "제한 능력자"], "민법에서 만 19세 미만의 미성년자는 제한 능력자로 보아, 법정 대리인(보통 부모)의 동의 없이 한 계약을 취소할 수 있어요. 판단 능력이 부족한 미성년자를 보호하기 위한 것이에요. 다만 허락받은 용돈 범위 안의 처분이나 권리만 얻는 행위는 혼자 할 수 있고, 속임수로 성년인 척했다면 취소할 수 없어요.\n예: 고등학생이 부모 동의 없이 비싼 노트북을 할부로 샀다면 계약을 취소할 수 있어요."),
        ce(.high, "개인 생활과 법", ["불법 행위", "손해 배상"], "불법 행위는 고의나 과실로 위법하게 다른 사람에게 손해를 끼친 행위로, 가해자는 손해를 배상할 책임을 져요(민법 제750조). 원칙적으로 잘못이 있어야 책임을 지는 과실 책임주의를 따르지만, 감독자 책임이나 사용자 책임처럼 특수한 불법 행위도 있어요.\n예: 공놀이를 하다 실수로 이웃집 유리창을 깼다면 손해를 배상해야 해요."),
        ce(.high, "개인 생활과 법", ["죄형 법정주의", "소급 처벌 금지"], "죄형 법정주의는 어떤 행위가 범죄이고 어떤 형벌을 받는지가 미리 법률로 정해져 있어야 한다는 형법의 기본 원칙이에요. '법률 없으면 범죄도 형벌도 없다'는 말로 표현돼요. 그래서 관습법으로 처벌할 수 없고, 행위 후에 만든 법으로 처벌하는 소급 처벌과 피고인에게 불리한 유추 해석이 금지돼요.\n예: 아무리 비난받을 행동이라도 처벌하는 법률이 없으면 처벌할 수 없어요."),
        ce(.high, "개인 생활과 법", ["범죄의 성립 요건", "구성 요건 해당성"], "범죄가 성립하려면 세 가지 요건을 모두 갖추어야 해요. 법률이 정한 범죄 행위에 해당하는 구성 요건 해당성, 정당방위처럼 위법성을 없애는 사유가 없는 위법성, 행위자를 비난할 수 있는 책임이에요. 만 14세 미만의 형사 미성년자는 책임이 없어 형벌을 받지 않아요.\n예: 강도를 막으려고 상대를 밀친 행위는 정당방위로 인정되면 범죄가 되지 않아요."),
        ce(.high, "개인 생활과 법", ["근로 3권", "노동 3권"], "근로 3권은 근로자가 사용자와 대등한 위치에서 근로 조건을 정할 수 있도록 헌법이 보장한 권리예요. 노동조합을 만들 수 있는 단결권, 노동조합이 사용자와 근로 조건을 협상하는 단체 교섭권, 협상이 결렬되었을 때 파업 등을 할 수 있는 단체 행동권이 있어요.\n예: 근로자들이 노동조합을 통해 임금 인상을 요구하며 회사와 협상하는 것이에요."),
        ce(.high, "개인 생활과 법", ["근로 기준법", "부당 해고"], "근로 기준법은 근로 조건의 최저 기준을 정한 법으로, 근로 계약서 작성, 임금, 근로 시간, 휴일 등을 정해요. 사용자는 정당한 이유 없이 근로자를 해고할 수 없고, 해고할 때는 사유와 시기를 서면으로 알려야 해요. 부당 해고를 당하면 노동 위원회에 구제를 신청할 수 있어요.\n예: 청소년도 아르바이트를 할 때 근로 계약서를 쓰고 최저 임금 이상을 받아야 해요."),

        ce(.high, "시장과 경제 활동", ["수요와 공급의 변동", "수요 변동", "공급 변동"], "가격 이외의 요인이 바뀌면 수요 곡선이나 공급 곡선 자체가 이동해요. 소득, 선호, 관련 상품 가격 등이 변하면 수요가, 생산 비용, 기술, 공급자 수 등이 변하면 공급이 변동해요. 수요가 증가하면 균형 가격과 거래량이 모두 늘고, 공급이 증가하면 균형 가격은 내리고 거래량은 늘어요.\n예: 무더위로 에어컨을 원하는 사람이 많아지면 수요 곡선이 오른쪽으로 이동해 가격이 올라요."),
        ce(.high, "시장과 경제 활동", ["가격 탄력성", "수요의 가격 탄력성"], "수요의 가격 탄력성은 가격이 변할 때 수요량이 얼마나 민감하게 변하는지 나타내요. 수요량 변화율을 가격 변화율로 나눈 값(절댓값)이 1보다 크면 탄력적, 1보다 작으면 비탄력적이에요. 대체재가 많거나 사치품일수록 탄력적이고, 생활필수품일수록 비탄력적이에요.\n예: 쌀처럼 비탄력적인 상품은 가격이 올라도 수요량이 크게 줄지 않아 판매 수입이 늘어요."),
        ce(.high, "시장과 경제 활동", ["시장 실패", "외부 효과", "정부 실패"], "시장 실패는 시장이 자원을 효율적으로 배분하지 못하는 상황이에요. 독과점, 공공재 부족, 외부 효과(대가 없이 남에게 이익이나 손해를 주는 것), 정보의 비대칭 등으로 나타나요. 정부는 공정 거래 제도, 세금과 보조금, 공공재 공급 등으로 이를 바로잡으려 하지만, 정부 개입이 오히려 비효율을 낳는 정부 실패가 생기기도 해요.\n예: 공장 폐수로 강이 오염되는데 공장이 그 비용을 치르지 않는 것은 시장 실패예요."),
        ce(.high, "시장과 경제 활동", ["공공재", "무임승차"], "공공재는 국방, 치안, 가로등처럼 여러 사람이 함께 소비하는 재화나 서비스예요. 대가를 내지 않은 사람도 소비에서 배제할 수 없는 비배제성과, 한 사람의 소비가 다른 사람의 소비를 줄이지 않는 비경합성을 가져요. 대가 없이 이용하려는 무임승차 문제로 시장에서 충분히 공급되지 않아 주로 정부가 공급해요.\n예: 등대는 공공재를 설명할 때 자주 드는 사례예요."),
        ce(.high, "시장과 경제 활동", ["국내 총생산", "GDP", "실질 GDP"], "국내 총생산(GDP)은 일정 기간 동안 한 나라 안에서 새로 생산된 최종 생산물의 시장 가치를 모두 합한 것이에요. 생산자의 국적과 관계없이 나라 안에서의 생산을 측정하며, 중간재, 중고품 거래, 가사 노동은 포함하지 않아요. 그해 가격으로 계산한 명목 GDP와 기준 연도 가격으로 계산한 실질 GDP가 있어요.\n예: 외국 기업이 우리나라 공장에서 만든 자동차도 우리나라 GDP에 들어가요."),
        ce(.high, "시장과 경제 활동", ["경기 변동", "경기 순환"], "경기 변동은 경제 활동이 활발해졌다가 침체되기를 반복하는 현상이에요. 보통 회복기, 호황기, 후퇴기, 불황기의 네 국면을 거쳐요. 호황기에는 생산과 고용이 늘고 물가가 오르기 쉬우며, 불황기에는 실업이 늘고 기업 이윤이 줄어요.\n예: 정부와 중앙은행은 불황기에 정부 지출을 늘리거나 금리를 낮춰 경기를 살리려 해요."),
        ce(.high, "시장과 경제 활동", ["인플레이션", "물가 상승"], "인플레이션은 물가가 지속적으로 오르는 현상이에요. 수요가 공급보다 빠르게 늘어 생기는 수요 견인 인플레이션과 원자재 가격, 임금 같은 생산비가 올라 생기는 비용 인상 인플레이션이 있어요. 화폐 가치가 떨어져 봉급 생활자와 예금자, 채권자는 불리해지고 실물 자산 보유자와 채무자는 유리해지는 경향이 있어요.\n예: 국제 유가가 크게 오르면 비용 인상 인플레이션이 나타날 수 있어요."),
        ce(.high, "시장과 경제 활동", ["실업", "실업률"], "실업은 일할 능력과 의사가 있는데도 일자리를 얻지 못한 상태예요. 더 나은 직장을 찾는 동안의 마찰적 실업, 산업 구조 변화로 생기는 구조적 실업, 불경기에 생기는 경기적 실업, 계절에 따른 계절적 실업이 있어요. 실업률은 경제 활동 인구 가운데 실업자가 차지하는 비율이에요.\n예: 공장 자동화로 일자리를 잃은 노동자의 실업은 구조적 실업이에요."),
        ce(.high, "시장과 경제 활동", ["환율", "원/달러 환율"], "환율은 자국 화폐와 외국 화폐를 바꾸는 비율로, 외환 시장에서 외화의 수요와 공급에 따라 결정돼요. 원/달러 환율이 오르면(원화 가치 하락) 수출에 유리하고 수입품 가격과 해외여행 비용이 올라가요. 환율이 내리면(원화 가치 상승) 반대 현상이 나타나요.\n예: 1달러에 1,200원이던 환율이 1,300원이 되면 같은 미국 물건을 사는 데 원화가 더 많이 들어요."),
        ce(.high, "시장과 경제 활동", ["비교 우위", "절대 우위"], "비교 우위는 어떤 상품을 다른 나라보다 더 적은 기회비용으로 생산할 수 있는 것을 말해요. 리카도는 한 나라가 모든 상품을 더 잘 만들더라도(절대 우위), 각 나라가 비교 우위가 있는 상품을 특화해 교역하면 양쪽 모두 이익을 얻는다고 설명했어요.\n예: 변호사가 비서보다 타자를 빨리 치더라도 변론에 집중하고 타자는 비서에게 맡기는 것이 서로에게 이득이에요."),
        ce(.high, "시장과 경제 활동", ["국제 수지", "경상 수지"], "국제 수지는 일정 기간 동안 한 나라가 외국과 거래하며 주고받은 돈을 정리한 것이에요. 상품 수출입의 상품 수지, 운송·여행 등의 서비스 수지, 임금·이자·배당의 본원 소득 수지, 대가 없이 주고받는 이전 소득 수지를 합쳐 경상 수지라고 해요. 이 밖에 자본 수지와 금융 계정이 있어요.\n예: 외국 관광객이 우리나라에서 많이 소비하면 서비스 수지가 개선돼요."),

        ce(.high, "개인과 사회 구조", ["사회 현상을 보는 관점", "거시적 관점과 미시적 관점"], "사회·문화 현상을 바라보는 관점은 크게 거시적 관점과 미시적 관점으로 나뉘어요. 기능론과 갈등론은 사회 구조나 제도 같은 큰 틀에서 사회를 분석하는 거시적 관점이고, 상징적 상호작용론은 개인 간 상호 작용과 의미 해석에 주목하는 미시적 관점이에요. 하나의 현상도 관점에 따라 다르게 해석돼요.\n예: 교육을 기능론은 사회 통합의 수단으로, 갈등론은 불평등을 대물림하는 수단으로 봐요."),
        ce(.high, "개인과 사회 구조", ["사회 이동", "세대 간 이동"], "사회 이동은 개인이나 집단의 사회적 위치(계층)가 바뀌는 것이에요. 계층의 높낮이가 바뀌는 수직 이동과 같은 계층 안에서 바뀌는 수평 이동, 한 사람의 생애 안에서 일어나는 세대 내 이동과 부모 세대와 비교한 세대 간 이동, 개인의 노력에 따른 개인적 이동과 사회 변동에 따른 구조적 이동이 있어요.\n예: 공장 노동자의 자녀가 의사가 되었다면 세대 간 상승 이동이에요."),
        ce(.high, "개인과 사회 구조", ["아노미 이론", "아노미", "머튼"], "아노미 이론은 일탈 행동을 사회 구조의 문제로 설명하는 이론이에요. 뒤르켐은 급격한 사회 변동으로 규범이 혼란한 상태를 아노미라고 했고, 머튼은 사회가 강조하는 문화적 목표와 이를 이룰 제도적 수단 사이의 괴리가 일탈을 낳는다고 보았어요.\n예: 부자가 되라는 목표는 강조되지만 합법적인 기회가 부족할 때 사기 같은 일탈이 생길 수 있다고 설명해요."),
        ce(.high, "개인과 사회 구조", ["차별 교제 이론", "서덜랜드"], "차별 교제 이론은 미국의 사회학자 서덜랜드가 제시한 이론으로, 일탈 행동도 다른 행동처럼 주변 사람과의 상호 작용을 통해 학습된다고 봐요. 일탈 행동을 하는 사람들과 자주, 오래, 가깝게 어울릴수록 일탈을 긍정하는 태도와 방법을 배우게 된다는 거예요.\n예: 비행 청소년 무리와 어울리다가 비행을 배우게 되는 경우를 설명해요."),
        ce(.high, "개인과 사회 구조", ["낙인 이론", "2차 일탈"], "낙인 이론은 어떤 행동이 일탈인지는 행동 자체보다 주변 사람들이 그 행동에 일탈이라는 꼬리표를 붙이는 데서 결정된다고 보는 이론이에요. 처음의 사소한 일탈(1차 일탈)에 낙인이 찍히면 스스로를 일탈자로 여기며 더 심한 2차 일탈로 이어질 수 있다고 설명해요. 베커, 레머트 등이 대표 학자예요.\n예: 한 번 실수한 학생을 계속 문제아로 대하면 정말 문제 행동이 늘어날 수 있어요."),
        ce(.high, "개인과 사회 구조", ["문화 이해의 관점", "총체론적 관점", "비교론적 관점"], "문화를 이해하는 관점에는 총체론적 관점, 비교론적 관점, 상대론적 관점이 있어요. 총체론적 관점은 문화의 한 요소를 다른 요소나 전체와 관련지어 이해하고, 비교론적 관점은 여러 사회의 문화를 비교해 공통점과 차이점을 찾아요. 상대론적 관점은 그 사회의 맥락에서 문화를 이해해요.\n예: 이슬람 사회의 돼지고기 금기를 종교, 기후, 생활 방식과 연결해 보면 총체론적 관점이에요."),

        ce(.high, "생활과 윤리", ["행복", "행복한 삶의 조건"], "통합사회에서는 행복을 삶에서 만족과 기쁨을 느끼는 상태로 보고, 그 기준이 시대와 지역에 따라 달라진다고 설명해요. 행복한 삶을 위해서는 질 높은 정주 환경, 경제적 안정, 민주주의의 발전, 도덕적 실천과 성찰이 필요해요. 아리스토텔레스는 행복을 인간 삶의 궁극적 목적으로 보았어요.\n예: 공원과 도서관 같은 쾌적한 생활 환경도 행복의 조건이 돼요."),
        ce(.high, "생활과 윤리", ["생태 중심주의", "대지 윤리", "인간 중심주의"], "생태 중심주의는 인간을 생태계의 한 구성원으로 보고, 생명체뿐 아니라 흙, 물 같은 무생물을 포함한 생태계 전체를 도덕적으로 고려해야 한다는 관점이에요. 자연을 인간의 이익을 위한 도구로 보는 인간 중심주의와 대비돼요. 레오폴드의 대지 윤리가 대표적이에요.\n예: 개발보다 습지 생태계 전체의 보전을 우선하자는 주장이 생태 중심주의와 관련돼요."),
        ce(.high, "생활과 윤리", ["공자의 인", "인(仁)", "유교 윤리"], "공자는 춘추 시대의 사상가로 유교를 창시했어요. 사람을 사랑하는 마음인 인(仁)을 가장 중요한 덕으로 보고, 이를 예(禮)로 실천해야 한다고 했어요. 부모에게 효도하고 형제를 공경하는 효제를 인의 근본으로 보았고, 덕으로 다스리는 덕치를 주장했어요.\n예: 『논어』의 '내가 원하지 않는 것을 남에게 시키지 말라'는 말은 인을 실천하는 방법이에요."),
        ce(.high, "생활과 윤리", ["맹자의 성선설", "성선설", "사단"], "맹자는 사람의 본성이 본래 선하다는 성선설을 주장했어요. 누구나 측은지심, 수오지심, 사양지심, 시비지심의 네 가지 착한 마음(사단)을 타고나며, 이를 잘 키우면 인, 의, 예, 지의 덕을 이룰 수 있다고 했어요. 정치에서는 백성을 근본으로 하는 왕도 정치를 강조했어요.\n예: 우물에 빠지려는 아이를 보면 누구나 놀라 구하려는 마음이 드는 것이 측은지심이에요."),
        ce(.high, "생활과 윤리", ["순자의 성악설", "성악설"], "순자는 사람의 본성이 이익을 좋아하고 욕망을 따르기 쉬워, 그대로 두면 다툼이 생긴다는 성악설을 주장했어요. 그래서 예(禮)를 통한 교육과 노력으로 본성을 바로잡아야 한다고 보았어요(화성기위). 그의 사상은 제자인 한비자 등 법가에 영향을 주었어요.\n예: 사람은 배우고 노력해야 선해질 수 있다는 생각이 순자의 입장이에요."),
        ce(.high, "생활과 윤리", ["노자의 무위자연", "무위자연", "도가"], "노자는 도가 사상을 연 인물로, 인위적인 노력이나 제도를 버리고 자연의 흐름에 따라 사는 무위자연의 삶을 강조했어요. 물처럼 다투지 않고 낮은 곳으로 흐르는 겸손한 삶(상선약수)을 이상으로 보았고, 작은 나라 적은 백성(소국과민)의 사회를 꿈꾸었어요.\n예: 장자는 노자의 사상을 이어 모든 것을 차별 없이 보는 제물론과 정신적 자유(소요유)를 말했어요."),
        ce(.high, "생활과 윤리", ["롤스의 정의론", "공정으로서의 정의", "무지의 베일"], "롤스는 『정의론』(1971)에서 공정한 절차를 거쳐 합의된 원칙이 정의롭다고 보았어요. 자신의 처지를 모르는 '무지의 베일'을 쓴 원초적 입장에서 사람들은 모두에게 평등한 기본적 자유를 보장하는 제1원칙과, 공정한 기회 균등 및 최소 수혜자에게 최대 이익이 되게 하는 차등의 원칙인 제2원칙을 택할 것이라고 했어요.\n예: 사회적 약자를 우선 배려하는 복지 정책의 근거로 쓰여요."),

        // MARK: - 대학교

        ce(.university, "경제학원론", ["한계 효용 체감의 법칙", "한계 효용"], "한계 효용은 재화를 한 단위 더 소비할 때 추가로 얻는 만족(효용)이에요. 같은 재화를 계속 소비할수록 한계 효용이 점점 줄어드는 것을 한계 효용 체감의 법칙이라고 해요. 소비자는 각 재화에 쓴 마지막 1원당 한계 효용이 같아지도록 소비할 때 효용이 가장 커져요(한계 효용 균등의 법칙).\n예: 배고플 때 먹는 첫 번째 빵은 아주 맛있지만, 다섯 번째 빵은 그만큼 만족스럽지 않아요."),
        ce(.university, "경제학원론", ["소비자 잉여", "생산자 잉여", "총잉여"], "소비자 잉여는 소비자가 지불할 용의가 있는 최대 금액에서 실제로 지불한 금액을 뺀 값이에요. 생산자 잉여는 생산자가 실제로 받은 금액에서 최소한 받고자 했던 금액을 뺀 값이에요. 둘을 합한 총잉여는 경쟁 시장의 균형에서 가장 커지며, 이를 효율적이라고 해요.\n예: 3만 원까지 낼 생각이던 공연 표를 2만 원에 샀다면 소비자 잉여는 1만 원이에요."),
        ce(.university, "경제학원론", ["독점", "독점 기업", "자연 독점"], "독점은 하나의 기업이 시장 전체에 공급하며 가까운 대체재가 없는 시장이에요. 독점 기업은 가격 설정자로서 한계 수입과 한계 비용이 같아지는 수량을 생산하고, 경쟁 시장보다 높은 가격을 매겨요. 그 결과 거래량이 줄어 사회적 후생 손실(자중 손실)이 생겨요. 진입 장벽, 규모의 경제, 특허 등이 독점의 원인이에요.\n예: 전력망처럼 규모의 경제가 큰 산업에서는 자연 독점이 나타나기 쉬워요."),
        ce(.university, "경제학원론", ["가격 차별", "가격 차별화"], "가격 차별은 같은 상품을 소비자 집단에 따라 서로 다른 가격에 파는 전략이에요. 시장 지배력이 있고, 소비자 집단을 구분할 수 있으며, 소비자끼리 되팔기가 어려워야 가능해요. 수요의 가격 탄력성이 큰 집단에는 낮은 가격을, 작은 집단에는 높은 가격을 매겨요.\n예: 영화관의 조조 할인, 학생 할인, 항공권의 시기별 가격 차이가 가격 차별이에요."),
        ce(.university, "경제학원론", ["과점", "카르텔", "담합"], "과점은 소수의 기업이 시장의 대부분을 차지하는 시장이에요. 각 기업이 경쟁 기업의 반응을 고려해 결정하는 상호 의존성이 크고, 가격 경쟁보다 광고나 품질 같은 비가격 경쟁이 많아요. 기업들이 가격이나 생산량을 담합해 카르텔을 만들면 독점처럼 행동할 수 있어 법으로 금지해요.\n예: 이동 통신, 정유 산업이 과점 시장의 예로 자주 거론돼요."),
        ce(.university, "경제학원론", ["게임 이론", "전략적 상호 작용"], "게임 이론은 여러 경제 주체가 서로의 선택을 예상하며 전략적으로 행동하는 상황을 분석하는 이론이에요. 폰 노이만과 모르겐슈테른이 체계화했고, 경기자, 전략, 보수(결과)로 게임을 나타내요. 과점 기업의 경쟁, 국가 간 협상, 경매 등 다양한 분야에 쓰여요.\n예: 두 편의점이 가격을 내릴지 유지할지 서로의 반응을 예상하며 결정하는 상황을 분석해요."),
        ce(.university, "경제학원론", ["내시 균형", "존 내시"], "내시 균형은 상대방의 전략이 주어졌을 때 어떤 경기자도 자신의 전략을 바꿀 유인이 없는 상태예요. 즉 모두가 상대 전략에 대한 최선의 대응을 선택하고 있는 전략 조합이에요. 수학자 존 내시가 제시했고, 그는 이 연구로 1994년 노벨 경제학상을 받았어요. 내시 균형이 반드시 모두에게 가장 좋은 결과인 것은 아니에요.\n예: 죄수의 딜레마에서 둘 다 자백하는 것이 내시 균형이에요."),
        ce(.university, "경제학원론", ["죄수의 딜레마", "죄수 딜레마"], "죄수의 딜레마는 각자가 자신에게 가장 유리한 선택을 했는데 결과적으로 모두에게 더 나쁜 결과가 나타나는 상황이에요. 따로 조사받는 두 공범은 상대가 어떤 선택을 하든 자백하는 것이 유리해 둘 다 자백하지만, 둘 다 침묵했다면 더 가벼운 형을 받았을 거예요. 개인의 합리성과 집단의 합리성이 어긋날 수 있음을 보여 줘요.\n예: 과점 기업들이 서로 광고비를 늘리는 경쟁이 대표적인 사례예요."),
        ce(.university, "경제학원론", ["통화 정책", "기준 금리"], "통화 정책은 중앙은행이 통화량과 금리를 조절해 물가와 경기를 안정시키는 정책이에요. 우리나라는 한국은행이 기준 금리를 정해요. 경기가 침체되면 금리를 낮추는 확장적 통화 정책을, 물가가 크게 오르면 금리를 올리는 긴축적 통화 정책을 써요. 공개 시장 운영, 지급 준비율, 재할인율 조정 등의 수단이 있어요.\n예: 기준 금리를 올리면 대출 이자가 올라 소비와 투자가 줄어드는 경향이 있어요."),
        ce(.university, "경제학원론", ["재정 정책", "자동 안정화 장치"], "재정 정책은 정부가 세금과 정부 지출을 조절해 경기를 안정시키는 정책이에요. 불황기에는 정부 지출을 늘리거나 세금을 줄이는 확장적 재정 정책을, 경기 과열기에는 반대로 긴축적 재정 정책을 써요. 누진세나 실업 급여처럼 경기 변동을 저절로 완화하는 장치를 자동 안정화 장치라고 해요.\n예: 경기 침체기에 정부가 도로·철도 건설을 늘리는 것은 확장적 재정 정책이에요."),
        ce(.university, "경제학원론", ["승수 효과", "정부 지출 승수", "구축 효과"], "승수 효과는 정부 지출이나 투자가 처음 늘어난 금액보다 국민 소득이 더 크게 늘어나는 효과예요. 지출이 누군가의 소득이 되고 그 일부가 다시 소비되는 과정이 반복되기 때문이에요. 간단한 모형에서 정부 지출 승수는 1을 (1 - 한계 소비 성향)으로 나눈 값이에요. 다만 금리가 올라 민간 투자가 줄어드는 구축 효과가 있으면 효과가 작아져요.\n예: 한계 소비 성향이 0.8이면 승수는 5예요."),

        ce(.university, "정치학개론", ["권력", "정치권력", "권위"], "막스 베버는 권력을 다른 사람의 저항에도 불구하고 자신의 의지를 관철할 수 있는 가능성으로 정의했어요. 정치권력은 국가 같은 정치 공동체에서 강제력을 바탕으로 사회 질서를 유지하고 정책을 집행하는 힘이에요. 권력이 정당성을 얻어 사람들이 자발적으로 따르게 되면 이를 권위라고 해요.\n예: 경찰이 교통 법규 위반을 단속하는 것은 국가 권력의 행사예요."),
        ce(.university, "정치학개론", ["정당성", "지배의 세 가지 유형"], "정당성은 권력이나 지배가 옳다고 인정받아 구성원이 자발적으로 따르게 되는 근거예요. 막스 베버는 지배의 정당성을 전통적 지배(관습과 전통), 카리스마적 지배(지도자의 비범한 자질), 합법적 지배(합리적으로 만든 법과 절차)로 구분했어요. 근대 국가는 주로 합법적 지배에 바탕을 둬요.\n예: 선거로 뽑힌 대통령이 헌법에 따라 권한을 행사하는 것은 합법적 지배예요."),
        ce(.university, "정치학개론", ["정당", "양당제", "다당제"], "정당은 정치적 견해를 같이하는 사람들이 정권 획득을 목표로 모인 조직이에요. 국민의 다양한 의견을 모아 정책으로 만들고(이익 집약), 선거에 후보를 내며, 정부를 운영하거나 비판·견제해요. 정권 획득을 직접 목표로 한다는 점에서 이익 집단이나 시민 단체와 달라요. 정당의 수에 따라 양당제와 다당제 등으로 나눠요.\n예: 선거에서 다수 의석을 얻은 정당은 정책을 입법으로 실현하기 쉬워요."),
        ce(.university, "정치학개론", ["다원주의", "다원주의 민주주의론"], "다원주의는 사회에 다양한 이익 집단이 존재하고, 이들이 경쟁하고 타협하는 과정에서 정책이 결정된다고 보는 민주주의 이론이에요. 권력이 여러 집단에 분산되어 있어 어느 한 집단이 권력을 독점하기 어렵다고 봐요. 로버트 달이 대표 학자이며, 자원이 많은 집단의 영향력이 더 크다는 비판도 받아요.\n예: 노동계, 경영계, 시민 단체가 각자 의견을 내고 협상해 법안이 수정되는 과정을 설명해요."),
        ce(.university, "정치학개론", ["엘리트 이론", "엘리트주의", "과두제의 철칙"], "엘리트 이론은 어느 사회에서든 소수의 엘리트가 권력을 쥐고 다수의 대중을 이끈다고 보는 이론이에요. 파레토, 모스카, 미헬스 등이 대표 학자이며, 밀스는 미국 사회를 정치·경제·군사 엘리트가 지배한다고 분석했어요. 슘페터는 민주주의를 엘리트들이 선거에서 표를 두고 경쟁하는 절차로 보았어요.\n예: 거대 조직일수록 소수 지도부가 권력을 장악한다는 미헬스의 '과두제의 철칙'이 유명해요."),
        ce(.university, "정치학개론", ["심의 민주주의", "숙의 민주주의", "대의 민주주의"], "심의(숙의) 민주주의는 단순히 다수결로 결정하기보다 시민들이 충분한 정보를 바탕으로 자유롭고 평등하게 토론하며 합리적인 합의를 찾아가는 과정을 중시하는 이론이에요. 대표에게 결정을 맡기는 대의 민주주의를 보완하려는 시도로, 하버마스의 의사소통 이론이 중요한 바탕이 되었어요.\n예: 무작위로 뽑힌 시민들이 전문가 설명을 듣고 토론해 정책 권고안을 내는 공론화 위원회가 그 예예요."),

        ce(.university, "사회학개론", ["기능론", "구조 기능주의"], "기능론은 사회를 여러 부분이 각자 기능을 하며 전체의 유지와 안정에 기여하는 유기체처럼 보는 거시적 관점이에요. 사회 제도는 저마다 필요한 기능을 하며, 사회는 합의된 가치를 바탕으로 균형을 이룬다고 봐요. 뒤르켐, 파슨스, 머튼이 대표 학자이며, 사회 변동과 갈등을 잘 설명하지 못한다는 비판을 받아요.\n예: 학교가 사회에 필요한 지식과 규범을 전달해 사회 통합에 기여한다고 설명해요."),
        ce(.university, "사회학개론", ["갈등론", "갈등 이론"], "갈등론은 사회를 한정된 자원과 권력을 둘러싸고 집단들이 대립하고 경쟁하는 장으로 보는 거시적 관점이에요. 사회 질서는 합의가 아니라 지배 집단의 강제로 유지되며, 갈등이 사회 변동의 원동력이라고 봐요. 마르크스, 다렌도르프 등이 대표 학자예요.\n예: 학교 교육이 지배 집단의 가치를 전달해 계층 불평등을 대물림한다고 설명해요."),
        ce(.university, "사회학개론", ["상징적 상호작용론", "거울 자아"], "상징적 상호작용론은 사람들이 언어, 몸짓 같은 상징을 통해 서로의 행동에 의미를 부여하고 해석하는 과정에 주목하는 미시적 관점이에요. 사회는 고정된 구조가 아니라 개인들의 끊임없는 상호 작용으로 만들어진다고 봐요. 미드, 블루머, 쿨리(거울 자아) 등이 대표 학자예요.\n예: 같은 미소도 상황과 관계에 따라 친근함이나 비웃음으로 다르게 해석될 수 있어요."),
        ce(.university, "사회학개론", ["마르크스의 계급론", "계급론"], "마르크스는 생산 수단을 소유했는지에 따라 사회를 지배 계급과 피지배 계급으로 나누었어요. 자본주의 사회에서는 생산 수단을 가진 자본가(부르주아)가 노동력만 가진 노동자(프롤레타리아)를 착취한다고 보았어요. 계층을 경제적 요인 한 가지로 구분하는 일원론적 관점이에요.\n예: 공장 소유주와 그 공장에서 임금을 받고 일하는 노동자의 관계를 계급 관계로 설명해요."),
        ce(.university, "사회학개론", ["베버의 계층론", "다원론적 계층론", "사회 계층론"], "베버는 사회 불평등을 경제적 차원(계급), 사회적 차원(지위·위신), 정치적 차원(권력)으로 나누어 설명했어요. 세 차원이 반드시 일치하지는 않는다고 보는 다원론적 관점이에요. 계층은 서열화된 연속적인 위치로 나타나며, 계층 간 이동이 가능하다고 봐요.\n예: 소득은 높지 않지만 사회적 존경을 많이 받는 성직자의 위치를 설명할 수 있어요."),
        ce(.university, "사회학개론", ["관료제", "목적 전치"], "관료제는 대규모 조직을 효율적으로 운영하기 위해 업무를 전문적으로 나누고 위계에 따라 관리하는 조직 형태예요. 베버는 분업과 전문화, 위계 서열, 문서화된 규칙, 경력과 실적에 따른 승진 등을 특징으로 설명했어요. 효율적이지만 목적보다 규칙을 앞세우는 목적 전치, 인간 소외, 무사안일 같은 문제가 생길 수 있어요.\n예: 서류 절차를 지키느라 정작 급한 민원을 늦게 처리하는 것이 목적 전치예요."),

        ce(.university, "심리학개론", ["고전적 조건형성", "파블로프의 개 실험"], "고전적 조건형성은 원래 반응을 일으키지 않던 중성 자극이 반응을 일으키는 무조건 자극과 반복해서 짝지어지면, 나중에는 그 자극만으로도 반응이 나타나는 학습이에요. 러시아의 생리학자 파블로프가 개 실험으로 발견했어요. 이때 학습된 자극을 조건 자극, 학습된 반응을 조건 반응이라고 해요.\n예: 종소리와 먹이를 함께 주자 나중에는 종소리만 들어도 개가 침을 흘렸어요."),
        ce(.university, "심리학개론", ["조작적 조건형성", "강화와 처벌", "스키너 상자"], "조작적 조건형성은 행동 뒤에 따르는 결과에 따라 그 행동의 빈도가 달라지는 학습이에요. 손다이크의 효과의 법칙을 바탕으로 스키너가 체계화했어요. 행동을 늘리는 것을 강화, 줄이는 것을 처벌이라 하고, 좋은 것을 주는지(정적) 싫은 것을 없애는지(부적)에 따라 나뉘어요.\n예: 숙제를 끝내면 잔소리가 멈춰서 숙제를 더 잘하게 되는 것은 부적 강화예요."),
        ce(.university, "심리학개론", ["관찰 학습", "사회 학습 이론", "대리 강화"], "관찰 학습은 다른 사람(모델)의 행동과 그 결과를 보는 것만으로 행동을 배우는 것이에요. 반두라가 사회 학습 이론으로 제시했어요. 직접 보상을 받지 않아도 모델이 보상받는 것을 보면 그 행동을 따라 하게 되는데, 이를 대리 강화라고 해요.\n예: 반두라의 보보 인형 실험에서 어른이 인형을 때리는 것을 본 아이들은 인형을 더 공격적으로 다뤘어요."),
        ce(.university, "심리학개론", ["인지 부조화", "인지 부조화 이론"], "인지 부조화는 자신의 믿음이나 태도와 행동이 서로 맞지 않을 때 느끼는 불편한 심리 상태예요. 페스팅거가 제시했으며, 사람들은 이 불편함을 줄이려고 태도를 바꾸거나 행동을 합리화하는 경향이 있어요.\n예: 담배가 해롭다는 것을 알면서도 피우는 사람이 '스트레스를 푸는 데는 도움이 된다'고 스스로를 설득하는 거예요."),
        ce(.university, "심리학개론", ["매슬로의 욕구 위계", "욕구 단계설", "자아실현"], "매슬로는 인간의 욕구가 위계를 이루며, 아래 단계의 욕구가 어느 정도 충족되어야 위 단계의 욕구가 나타난다고 보았어요. 생리적 욕구, 안전 욕구, 소속과 애정 욕구, 존중 욕구, 자아실현 욕구의 다섯 단계로 흔히 설명해요. 실제로는 단계가 엄격한 순서대로 나타나지 않는다는 비판도 있어요.\n예: 끼니를 걱정하는 사람은 자아실현보다 먹고사는 문제를 먼저 해결하려 할 거예요."),
        ce(.university, "심리학개론", ["피아제의 인지 발달 단계", "피아제", "보존 개념"], "피아제는 아동이 환경과 상호 작용하며 스스로 지식을 구성한다고 보고 인지 발달을 네 단계로 나눴어요. 감각 운동기(0~2세, 대상 영속성), 전조작기(2~7세, 자기중심성), 구체적 조작기(7~11세, 보존 개념), 형식적 조작기(11세 이후, 추상적 사고)예요. 동화와 조절을 통해 발달한다고 했어요.\n예: 같은 양의 물을 가늘고 긴 컵에 옮기면 양이 많아졌다고 생각하는 것은 전조작기의 특징이에요."),
        ce(.university, "심리학개론", ["동조", "애쉬의 동조 실험"], "동조는 집단의 압력 때문에 개인이 자신의 판단이나 행동을 집단에 맞추는 현상이에요. 애쉬의 실험에서 참가자들은 선의 길이를 비교하는 쉬운 문제에서도, 다른 사람들이 일부러 틀린 답을 말하자 상당수가 그 답을 따랐어요. 집단의 크기, 만장일치 여부 등이 동조에 영향을 줘요.\n예: 한 명이라도 다른 의견을 내는 사람이 있으면 동조가 크게 줄어들어요."),

        ce(.university, "법학개론", ["법원(法源)", "법의 연원", "성문법과 불문법"], "법원(法源)은 법이 존재하는 형태, 즉 재판의 기준이 되는 법의 근원을 말해요. 문서로 만들어진 성문법(헌법, 법률, 명령, 규칙, 조례, 조약)과 문서 형태가 아닌 불문법(관습법, 판례법, 조리)으로 나뉘어요. 우리나라는 성문법을 중심으로 하는 대륙법계 국가예요.\n예: 민법 제1조는 민사에 관해 법률에 규정이 없으면 관습법에, 관습법이 없으면 조리에 따른다고 정하고 있어요."),
        ce(.university, "법학개론", ["판례", "판례법", "선례 구속의 원칙"], "판례는 법원이 구체적인 사건에 대해 내린 판결로, 비슷한 사건의 재판 기준이 되기도 해요. 영미법계 국가에서는 앞선 판결을 따라야 하는 선례 구속의 원칙이 있어 판례가 중요한 법원이에요. 대륙법계인 우리나라에서는 판례에 일반적인 법적 구속력이 인정되지 않지만, 대법원 판례는 실제로 하급 법원에 큰 영향을 줘요.\n예: 대법원 전원 합의체가 기존 판례를 바꾸면 이후 비슷한 사건의 판단이 달라져요."),
        ce(.university, "법학개론", ["법의 해석", "유추 해석", "확장 해석"], "법의 해석은 추상적인 법 규정의 의미를 구체적인 사건에 적용할 수 있도록 밝히는 일이에요. 국가 기관이 하는 유권 해석과 학자 등이 하는 학리 해석이 있어요. 학리 해석에는 글자 뜻에 따르는 문리 해석과, 법의 목적과 체계를 고려하는 논리 해석(확장·축소·반대·유추 해석 등)이 있어요.\n예: '개 출입 금지' 규정을 비슷한 다른 동물에도 적용하는 것은 유추 해석인데, 형법에서는 피고인에게 불리한 유추 해석이 금지돼요."),
        ce(.university, "법학개론", ["법 적용의 원칙", "특별법 우선의 원칙", "신법 우선의 원칙"], "여러 법이 충돌할 때는 일정한 원칙에 따라 적용해요. 상위법이 하위법보다 우선하는 상위법 우선의 원칙, 특정한 사람·사항에 적용되는 특별법이 일반법보다 우선하는 특별법 우선의 원칙, 나중에 만든 신법이 구법보다 우선하는 신법 우선의 원칙이 있어요. 또 법은 원칙적으로 시행 이전의 일에 적용되지 않아요(법률 불소급의 원칙).\n예: 상거래에는 일반법인 민법보다 특별법인 상법이 먼저 적용돼요."),
        ce(.university, "법학개론", ["법의 이념", "법적 안정성", "합목적성"], "독일의 법철학자 라드브루흐는 법이 추구하는 이념으로 정의, 합목적성, 법적 안정성을 들었어요. 정의는 같은 것은 같게 다른 것은 다르게 대하는 것, 합목적성은 법이 사회가 추구하는 목적에 맞는 것, 법적 안정성은 법이 함부로 바뀌지 않아 사람들이 믿고 행동할 수 있는 것이에요. 세 이념은 서로 충돌하기도 해요.\n예: 공소 시효 제도는 법적 안정성을 중시한 제도로 설명돼요."),

        ce(.university, "철학 입문", ["소크라테스", "문답법", "산파술"], "소크라테스(기원전 470년경~399년)는 고대 아테네의 철학자로, 델포이 신전의 '너 자신을 알라'는 말을 중시하며 자신의 무지를 깨닫는 것이 지혜의 출발이라고 했어요. 질문과 대답을 거듭해 상대가 스스로 진리를 깨닫게 하는 문답법(산파술)을 썼고, 덕을 알면 실천하게 된다는 지행합일을 주장했어요. 아테네 법정에서 사형 판결을 받고 독배를 마셨어요.\n예: 그의 사상은 제자 플라톤의 대화편으로 전해져요."),
        ce(.university, "철학 입문", ["플라톤", "이데아론", "동굴의 비유"], "플라톤(기원전 427년경~347년)은 소크라테스의 제자로, 감각으로 경험하는 현실 세계는 참된 실재인 이데아 세계의 그림자에 불과하다는 이데아론을 주장하고 이를 동굴의 비유로 설명했어요. 영혼의 이성·기개·욕망이 각각 지혜·용기·절제의 덕을 갖추고 조화를 이룰 때 정의롭다고 보았어요.\n예: 『국가』에서 철학자가 다스리는 철인 정치를 이상 국가로 제시했어요."),
        ce(.university, "철학 입문", ["아리스토텔레스", "중용", "덕 윤리"], "아리스토텔레스(기원전 384년~322년)는 플라톤의 제자로, 이데아가 현실과 떨어져 있다는 스승의 생각을 비판하고 사물 안에서 본질을 찾으려 했어요. 행복(에우다이모니아)을 삶의 궁극적 목적으로 보고, 지나침과 모자람 사이의 중용을 습관으로 길러야 한다는 덕 윤리를 제시했어요. 논리학, 정치학, 생물학 등 여러 학문의 기초를 닦았어요.\n예: 용기는 무모함과 비겁함 사이의 중용이라고 설명했어요."),
        ce(.university, "철학 입문", ["데카르트", "방법적 회의", "합리론"], "데카르트(1596~1650)는 프랑스의 철학자이자 수학자로, 근대 철학의 아버지라 불려요. 확실한 지식을 얻으려고 의심할 수 있는 모든 것을 의심하는 방법적 회의를 거쳐, 의심하고 있는 나 자신은 의심할 수 없다는 결론에 이르렀어요. 이성을 지식의 근원으로 보는 합리론을 대표하며, 정신과 물질을 별개의 실체로 보는 심신 이원론을 주장했어요.\n예: '나는 생각한다, 그러므로 나는 존재한다'는 말이 유명해요."),
        ce(.university, "철학 입문", ["칸트", "정언 명령", "의무론"], "칸트(1724~1804)는 독일의 철학자로, 도덕적 행위는 결과가 아니라 의무에서 나온 선의지에 따라야 한다는 의무론 윤리를 세웠어요. 조건 없이 따라야 하는 정언 명령으로 '너의 행위 원칙이 보편적 법칙이 될 수 있도록 행위하라', '인간을 언제나 목적으로 대하고 결코 수단으로만 대하지 말라'를 제시했어요.\n예: 거짓말이 이익이 되더라도 모두가 거짓말하는 세상을 바랄 수 없으므로 하면 안 된다고 봐요."),
        ce(.university, "철학 입문", ["공리주의", "최대 다수의 최대 행복", "벤담과 밀"], "공리주의는 행위의 옳고 그름을 그 결과가 가져오는 유용성(쾌락과 행복)으로 판단하는 윤리 이론이에요. 벤담은 '최대 다수의 최대 행복'을 내세우며 쾌락을 양적으로 계산할 수 있다고 보았고(양적 공리주의), 밀은 쾌락에도 질적 차이가 있다고 했어요(질적 공리주의). 다수의 이익을 위해 소수의 권리가 희생될 수 있다는 비판을 받아요.\n예: 밀은 만족한 돼지보다 불만족한 인간이 낫다고 말했어요."),
        ce(.university, "철학 입문", ["실존주의", "실존은 본질에 앞선다"], "실존주의는 인간을 정해진 본질에 따라 사는 존재가 아니라 스스로 선택하고 책임지며 자신을 만들어 가는 존재로 보는 사상이에요. 키르케고르, 하이데거, 야스퍼스, 사르트르 등이 대표적이에요. 사르트르는 '실존은 본질에 앞선다'고 말하며 인간은 자유로운 선택에 대해 전적인 책임을 진다고 강조했어요.\n예: 정해진 운명 없이 자신의 진로를 스스로 선택하고 그 결과를 책임지는 태도를 강조해요."),
        ce(.university, "철학 입문", ["경험론", "영국 경험론", "타불라 라사"], "경험론은 모든 지식이 감각 경험에서 비롯된다고 보는 철학적 입장이에요. 베이컨은 관찰과 실험에 바탕을 둔 귀납법을 강조했고, 로크는 사람의 마음이 태어날 때 백지(타불라 라사)와 같다고 했으며, 흄은 인과 관계도 습관적인 연상일 뿐이라고 의심했어요. 이성을 중시한 대륙의 합리론과 대비돼요.\n예: '아는 것이 힘이다'는 베이컨의 말로 알려져 있어요."),
        ce(.university, "철학 입문", ["사회 계약설", "사회 계약론"], "사회 계약설은 국가가 자유롭고 평등한 개인들의 합의(계약)로 만들어졌다고 보는 이론이에요. 홉스는 '만인에 대한 만인의 투쟁' 상태를 벗어나려 강력한 국가에 권리를 넘긴다고 했고, 로크는 생명·자유·재산을 지키려 국가를 세우며 국가가 이를 어기면 저항할 수 있다고 했어요. 루소는 일반 의지에 따른 국민 주권을 강조했어요.\n예: 로크의 저항권 사상은 미국 독립 선언에 영향을 주었어요."),

        ce(.university, "국제관계론", ["현실주의", "신현실주의", "구조적 현실주의"], "현실주의는 국제 사회를 중앙 정부가 없는 무정부 상태로 보고, 국가는 생존과 국익을 위해 힘을 추구하는 합리적 행위자라고 보는 이론이에요. 모겐소는 국가 간 권력 투쟁을 강조했고, 왈츠의 신현실주의는 국제 체제의 구조가 국가 행동을 제약한다고 설명했어요. 국제 협력은 불안정하며 군사력이 가장 중요하다고 봐요.\n예: 이웃 나라의 군비 증강에 맞서 자국도 군사력을 키우는 행동을 잘 설명해요."),
        ce(.university, "국제관계론", ["자유주의 국제관계 이론", "신자유주의 제도주의", "민주 평화론"], "자유주의 국제관계 이론은 국가 간 협력과 평화가 가능하다고 보는 이론이에요. 경제적 상호 의존, 국제기구와 국제 규범, 민주주의의 확산이 갈등을 줄인다고 봐요. 코헤인 등의 신자유주의 제도주의는 국제 제도가 정보를 공유하게 하고 배신을 줄여 협력을 돕는다고 설명해요.\n예: 민주주의 국가끼리는 전쟁을 거의 하지 않는다는 민주 평화론도 자유주의의 주장이에요."),
        ce(.university, "국제관계론", ["세력 균형", "힘의 균형"], "세력 균형은 어느 한 국가나 동맹이 압도적인 힘을 갖지 못하도록 여러 국가가 힘의 균형을 이루어 평화와 안정을 유지하는 상태나 정책이에요. 강대국이 떠오르면 다른 나라들이 동맹을 맺거나 군사력을 키워 견제해요. 현실주의의 핵심 개념이며, 19세기 유럽의 빈 체제가 대표적 사례로 꼽혀요.\n예: 한 나라가 지나치게 강해지자 주변국들이 연합해 맞서는 것이에요."),
